    code: "// NAME: Flipping Hexagons\nuniform float speed; // @min 0.1 @max 5.0 @default 1.5\nuniform float gridSize; // @min 1.0 @max 50.0 @default 10.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec2 p = (uv - 0.5) * 2.0;\np.x *= resolution.x / resolution.y;\nvec2 r = vec2(1.0, 1.7320508);\nvec2 h = r * 0.5;\nvec2 p_scaled = p * gridSize;\nvec2 a = mod(p_scaled, r) - h;\nvec2 b = mod(p_scaled - h, r) - h;\nvec2 hex = dot(a, a) < dot(b, b) ? a : b;\nvec2 id = p_scaled - hex;\nfloat localTime = time * speed - length(id) * 0.2;\nfloat phase = fract(localTime);\nfloat flip = smoothstep(0.0, 0.4, phase);\nfloat angle = (floor(localTime) + flip) * 3.14159;\nmat2 rot = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));\nvec2 flippedHex = rot * hex;\nvec2 finalUV = (id + flippedHex) / gridSize;\nfinalUV.x /= (resolution.x / resolution.y);\nfinalUV = finalUV * 0.5 + 0.5;\nvec4 col = texture2D(tex, finalUV);\nfloat shade = mix(1.0, 0.5, sin(flip * 3.14159));\ncol.rgb *= shade;\nfloat d = max(abs(flippedHex.x) * 0.866025 + abs(flippedHex.y) * 0.5, abs(flippedHex.y));\ncol.rgb *= smoothstep(0.48, 0.45, d);\nreturn col;\n}",
