    code: "// NAME: Anti-Gravity Shatter Morph\nuniform float complexity; // @min 5.0 @max 20.0 @default 12.0\nuniform float speed; // @min 0.1 @max 3.0 @default 0.8\nuniform float floorY; // @min 0.0 @max 0.5 @default 0.05\nuniform float gravity; // @min 1.0 @max 10.0 @default 4.0\nuniform float morphAmount; // @min 0.0 @max 1.0 @default 0.3\nuniform float centerScale; // @min 0.1 @max 5.0 @default 1.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nvec3 invertedRGB = 1.0 - source.rgb;\nfloat morphIntensity = dot(invertedRGB, vec3(0.299, 0.587, 0.114));\nvec2 distortedUV = uv;\ndistortedUV.y -= morphIntensity * morphAmount;\ndistortedUV.x += (uv.x - 0.5) * 2.0 * morphIntensity * morphAmount * 0.2;\ndistortedUV = (distortedUV - 0.5) * centerScale + 0.5;\nfloat ceilingY = 1.0 - floorY;\nif (distortedUV.y > ceilingY) {\nreturn texture2D(tex, distortedUV);\n}\nfloat cols = floor(complexity);\nfloat rows = floor(complexity);\nfloat cellX = floor(distortedUV.x * cols);\nfloat globalT = fract(time * speed * 0.3);\nfor (int i = 0; i < 20; i++) {\nif (float(i) >= rows) break;\nfloat cellY = float(i);\nfloat r = node_rand(vec2(cellX, cellY));\nfloat pieceT = max(0.0, globalT - r * 0.5) * 2.0;\nfloat rise = 0.5 * gravity * pieceT * pieceT;\nfloat maxRise = max(0.0, ceilingY - ((cellY + 1.0) / rows));\nfloat actualRise = min(rise, maxRise);\nfloat currentBottom = (cellY / rows) + actualRise;\nfloat currentTop = ((cellY + 1.0) / rows) + actualRise;\nif (distortedUV.y >= currentBottom && distortedUV.y < currentTop) {\nvec2 sampleUv = vec2(distortedUV.x, distortedUV.y - actualRise);\nreturn texture2D(tex, sampleUv);\n}\n}\nreturn vec4(0.0);\n}",
