    code: "// NAME: Infinite Strangler Vines\nuniform float timeScale; // @default 1.0\nuniform float vineDensity; // @min 1.0 @max 10.0 @default 4.0\nuniform vec3 vineColor; // @default 0.4,0.5,0.3\nuniform float blackThreshold; // @min 0.0 @max 1.0 @default 0.0\nuniform float morphIntensity; // @min 0.0 @max 5.0 @default 2.0\nmat2 rot(float a) {\nfloat c=cos(a), s=sin(a);\nreturn mat2(c,-s,s,c);\n}\nfloat smin(float a, float b, float r) {\nfloat h = clamp(0.5+0.5*(b-a)/r, 0.0, 1.0);\nreturn mix(b,a,h) - r*h*(1.0-h);\n}\nvec3 moda(vec2 p, float count) {\nfloat an = 6.283185 / count;\nfloat a = atan(p.y, p.x) + an * 0.5;\nfloat c = floor(a / an);\na = mod(a, an) - an * 0.5;\nreturn vec3(cos(a) * length(p), sin(a) * length(p), c);\n}\nfloat root(vec3 p, float count, float torsade, float width, float scale) {\np.xz *= rot(torsade);\nvec3 p1 = moda(p.xz, count);\np1.x -= width + 0.2 * sin(p1.z);\nreturn length(p1.xy) - scale;\n}\nfloat map(vec3 p, float t, float lum) {\nvec3 op = p;\np.z += dot(op.xy, op.xy) * 0.3 - lum * morphIntensity * 0.5;\np.x = mod(p.x + 0.8, 1.6) - 0.8;\nfloat trunkWidth = 0.25 + lum * 0.2 * morphIntensity;\nfloat roots = root(p, vineDensity, t + p.y * 0.5, trunkWidth, 0.1);\nroots = smin(roots, root(p, vineDensity + 1.5, -t - p.y * 0.3, trunkWidth + 0.05, 0.09), 0.4);\nvec3 lp = p;\nlp.y = mod(lp.y - t * 0.5, 0.4) - 0.2;\nfloat r = length(lp.xz) - trunkWidth - 0.15;\nfloat a = mod(atan(lp.z, lp.x), 0.8) - 0.4;\nfloat leaves = length(vec3(r, lp.y * 2.0, a * 2.0)) - 0.08;\nreturn smin(roots, leaves, 0.05) * 0.7;\n}\nvec3 calcNormal(vec3 p, float t, float lum) {\nvec2 e = vec2(0.01, 0.0);\nreturn normalize(vec3(\nmap(p+e.xyy, t, lum) - map(p-e.xyy, t, lum),\nmap(p+e.yxy, t, lum) - map(p-e.yxy, t, lum),\nmap(p+e.yyx, t, lum) - map(p-e.yyx, t, lum)\n));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 bg = texture2D(tex, uv);\nfloat bgLum = dot(bg.rgb, vec3(0.299, 0.587, 0.114));\nif (bgLum < blackThreshold) {\nreturn vec4(0.0, 0.0, 0.0, 1.0);\n}\nvec2 p_uv = (uv - 0.5) * 2.0;\np_uv.x *= resolution.x / resolution.y;\nvec3 ray = normalize(vec3(p_uv, 1.0));\nvec3 pos = vec3(0.0, 0.0, -2.5);\nfloat t = time * timeScale * 0.5;\nfloat dist = 0.0;\nfor(int i = 0; i < 40; i++) {\ndist = map(pos, t, bgLum);\nif(dist < 0.005 || pos.z > 10.0) break;\npos += ray * dist;\n}\nif (dist < 0.005) {\nvec3 n = calcNormal(pos, t, bgLum);\nvec3 l = normalize(vec3(1.0, 1.0, -1.0));\nfloat diff = max(dot(n, l), 0.0);\nvec3 col = vineColor * (diff + 0.2);\ncol = mix(col, bg.rgb, smoothstep(0.0, 10.0, pos.z + 2.5));\nreturn vec4(col, 1.0);\n}\nreturn vec4(0.0, 0.0, 0.0, 1.0);\n}",
