    code: "// NAME: Animated Fractal Vines\nuniform float growthSpeed; // @min 0.0 @max 5.0 @default 1.0\nuniform vec3 plantColor; // @default 0.15,0.4,0.1\nuniform float vineDensity; // @min 50.0 @max 250.0 @default 120.0\nuniform float curvature; // @min 0.0 @max 1.0 @default 0.3\nuniform float seed; // @min 0.0 @max 1000.0 @default 0.0\nuniform float mossDensity; // @min 0.0 @max 1.0 @default 0.6\nuniform float blackThreshold; // @min 0.0 @max 1.0 @default 0.05\nuniform float leafAmount; // @min 0.0 @max 2.0 @default 1.0\nuniform float leafSize; // @min 0.1 @max 3.0 @default 1.0\nuniform float leafShape; // @min 0.1 @max 5.0 @default 1.0\nuniform vec3 leafColor1; // @default 0.2,0.6,0.2\nuniform vec3 leafColor2; // @default 0.6,0.8,0.2\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat luma = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nfloat validArea = smoothstep(blackThreshold, blackThreshold + 0.01, luma);\nfloat cycleTime = time * growthSpeed * 0.05;\nfloat cycle = floor(cycleTime + 0.5);\nfloat s = seed + cycle * 13.37;\nvec2 eps = vec2(1.0) / max(resolution, vec2(1.0));\nvec2 safeUV = clamp(uv, eps * 2.0, 1.0 - eps * 2.0);\nfloat lR = dot(texture2D(tex, safeUV + vec2(eps.x, 0.0)).rgb, vec3(0.333));\nfloat lL = dot(texture2D(tex, safeUV - vec2(eps.x, 0.0)).rgb, vec3(0.333));\nfloat lT = dot(texture2D(tex, safeUV + vec2(0.0, eps.y)).rgb, vec3(0.333));\nfloat lB = dot(texture2D(tex, safeUV - vec2(0.0, eps.y)).rgb, vec3(0.333));\nvec2 grad = vec2(lR - lL, lT - lB);\nvec2 noiseWarp = vec2(node_noise(uv * 5.0 + vec2(s + time * 0.2)), node_noise(uv * 5.0 + vec2(3.14 + s - time * 0.15))) * 0.05;\nvec2 warpedUV = uv + grad * 1.5 + noiseWarp;\nvec2 vineUV = vec2(warpedUV.x * 25.0 + time * 0.5, warpedUV.y * 5.0 - time * 0.3);\nfloat n1 = node_noise(vineUV + vec2(s * 10.0));\nfloat vineDist = abs(n1 - 0.5) * 2.0;\nfloat vines2 = smoothstep(0.6, 0.2, vineDist);\nfloat mossNoise = node_noise(uv * 60.0 + vec2(s * 5.0 + time * 0.1)) * node_noise(uv * 120.0 - vec2(s));\nfloat mossBase = smoothstep(1.0 - mossDensity, 1.0, node_noise(uv * 10.0 + vec2(s * 2.0)));\nfloat moss = mossBase * smoothstep(0.2, 0.8, mossNoise) * 1.5;\nfloat progress = abs(fract(cycleTime) * 2.0 - 1.0) * 2.0 - 0.5;\nfloat organicShape = node_noise(uv * 3.0 + vec2(s + time * 0.3, time * 0.2)) * 0.6;\nfloat growthMask2 = smoothstep(progress + 0.5, progress, (1.0 - uv.y) + organicShape * 0.5);\nfloat combinedPlant = clamp(vines2 + moss, 0.0, 1.0);\nfloat plantMask2 = combinedPlant * growthMask2 * validArea;\nvec3 plant2 = plantColor * (luma * 0.6 + 0.2);\nvec3 colorAfterMoss = mix(vec3(0.0), plant2, plantMask2);\nfloat loopTime = time * growthSpeed / 6.0;\nfloat loopSeed = node_rand(vec2(floor(loopTime + 0.5), seed + 1.0)) * 100.0;\nfloat currentGrowth = abs(fract(loopTime) * 2.0 - 1.0) * 3.0 - 0.5;\nfloat n = node_noise(uv * 12.0 + vec2(loopSeed + time * 0.4, time * 0.25));\nfloat distortX = uv.x + luma * curvature + n * 0.05;\nfloat vX = distortX * vineDensity + time * 1.2;\nfloat vY = uv.y * 12.0 - time * 2.0;\nfloat strand1 = sin(vX + vY + loopSeed * 13.0);\nfloat strand2 = sin(vX - vY + loopSeed * 17.0);\nfloat thickness = mix(0.98, 0.92, luma);\nfloat topVines = smoothstep(thickness, 1.0, strand1) + smoothstep(thickness, 1.0, strand2);\nvec2 leafUV = uv * 5.0 / leafSize + vec2(loopSeed + time * 0.1);\nfloat fbm = 0.0;\nfloat amp = 0.5;\nvec2 p = leafUV;\nfor(int i = 0; i < 3; i++) {\nfbm += node_noise(p) * amp;\np = p * 2.0 + vec2(loopSeed);\namp *= 0.5;\n}\nfloat freqX = (2.0 + leafShape * fbm) * 0.333;\nfloat freqY = (3.0 + leafShape * fbm) * 0.333;\nfloat wX = sin(vX * freqX + fbm * 3.0);\nfloat wY = cos(vY * freqY + fbm * 3.0 + loopSeed);\nfloat leafWave = wX * wY;\nleafWave = sign(leafWave) * pow(abs(leafWave), 0.6);\nfloat leafDepth = fbm * leafWave;\nfloat leafThreshold = mix(0.2, 0.7, fbm);\nfloat leaves = smoothstep(leafThreshold, leafThreshold + 0.15, leafWave) * smoothstep(0.4, 1.0, max(strand1, strand2)) * leafAmount;\ntopVines = clamp(topVines + leaves * 1.5, 0.0, 1.0);\nfloat topMask = topVines * smoothstep(currentGrowth + 0.5, currentGrowth, (1.0 - uv.y) + n * 0.3) * validArea;\nvec3 mixedLeafColor = mix(leafColor1, leafColor2, fbm);\nvec3 topPlantColor = mix(plantColor * (luma * 0.8 + 0.2), mixedLeafColor * (0.5 + leafDepth * 0.5), clamp(leaves, 0.0, 1.0));\nvec3 finalColor = mix(colorAfterMoss, topPlantColor, topMask);\nreturn vec4(finalColor, source.a);\n}",
