    description: "Imported from shadertoexport for Sculpture use.",
    code: "// NAME: Oily Statue & Upside-Down Bubbles\nuniform float bubbleSize; // @min 0.05 @max 0.5 @default 0.2\nuniform float wobbleSpeed; // @min 0.0 @max 5.0 @default 1.0\nuniform float iridescence; // @min 0.0 @max 1.0 @default 0.8\nuniform float refraction; // @min 0.0 @max 0.5 @default 0.1\nuniform float blackThreshold; // @min 0.0 @max 1.0 @default 0.05\nuniform float bgShade; // @min 0.0 @max 1.0 @default 0.0\nuniform float oilIntensity; // @min 0.0 @max 1.0 @default 0.4\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 original = texture2D(tex, uv);\nfloat lum = dot(original.rgb, vec3(0.299, 0.587, 0.114));\nfloat n = node_noise(uv * 1.0 + time * 0.5);\nvec3 oil = 0.5 + 0.5 * cos(n * 8.0 + time + vec3(0.0, 2.0, 4.0));\nvec3 statueColor = mix(original.rgb, original.rgb * oil * 2.0, oilIntensity);\nvec4 baseColor = original;\nif (lum > blackThreshold) {\nbaseColor.rgb = statueColor;\n} else {\nbaseColor.rgb *= (1.0 - bgShade);\n}\nif (lum <= blackThreshold) {\nreturn baseColor;\n}\nvec4 finalColor = baseColor;\nfloat aspect = resolution.x / resolution.y;\nvec2 uvAspect = uv;\nuvAspect.x *= aspect;\nfor (int i = 0; i < 5; i++) {\nfloat fi = float(i);\nvec2 center = vec2(\n0.5 + 0.4 * sin(time * wobbleSpeed * 0.4 + fi * 2.3),\n0.5 + 0.4 * cos(time * wobbleSpeed * 0.3 + fi * 1.7)\n);\ncenter.x *= aspect;\nvec2 p = uvAspect - center;\nfloat dist = length(p);\nfloat angle = atan(p.y, p.x);\nfloat radius = bubbleSize * (0.6 + 0.1 * fi) + sin(angle * 4.0 + time * 3.0) * 0.005;\nif (dist < radius) {\nfloat z = sqrt(radius * radius - dist * dist);\nvec3 normal = normalize(vec3(p.x, p.y, z));\nfloat NdotV = max(dot(normal, vec3(0.0, 0.0, 1.0)), 0.0);\nvec2 distortedUV = uv - normal.xy * refraction * (1.0 - NdotV);\nvec4 bg = texture2D(tex, distortedUV);\nfloat bgLum = dot(bg.rgb, vec3(0.299, 0.587, 0.114));\nif (bgLum > blackThreshold) {\nfloat bgN = node_noise(distortedUV * 1.0 + time * 0.5);\nvec3 bgOil = 0.5 + 0.5 * cos(bgN * 8.0 + time + vec3(0.0, 2.0, 4.0));\nbg.rgb = mix(bg.rgb, bg.rgb * bgOil * 2.0, oilIntensity);\n} else {\nbg.rgb *= (1.0 - bgShade);\n}\nfloat fresnel = pow(1.0 - NdotV, 2.5);\nvec3 iriColor = 0.5 + 0.5 * cos(time * 0.5 + fresnel * 15.0 + vec3(0.0, 2.0, 4.0));\nvec3 lightDir = normalize(vec3(0.4, -0.8, 0.8));\nfloat spec = pow(max(dot(normal, lightDir), 0.0), 80.0) * 2.0;\nvec3 lightDir2 = normalize(vec3(-0.5, -0.3, 0.5));\nfloat spec2 = pow(max(dot(normal, lightDir2), 0.0), 40.0) * 0.8;\nvec3 bubbleColor = mix(bg.rgb, iriColor, iridescence * fresnel);\nbubbleColor += spec + spec2;\nfinalColor = vec4(bubbleColor, baseColor.a);\n}\n}\nreturn finalColor;\n}",
