    code: "// NAME: TD Shadow Warp\nuniform float speed; // @min 0.0 @max 2.0 @default 0.5\nuniform float complexity; // @min 1.0 @max 5.0 @default 4.0\nuniform float warpAmount; // @min 0.0 @max 1.0 @default 0.3\nuniform float chromaShift; // @min 0.0 @max 0.1 @default 0.03\nuniform float shadowThreshold; // @min 0.0 @max 1.0 @default 0.5\nuniform float blackThreshold; // @min 0.0 @max 0.5 @default 0.05\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 src = texture2D(tex, uv);\nfloat luma = dot(src.rgb, vec3(0.299, 0.587, 0.114));\nif (luma < blackThreshold) return src;\nfloat mask = smoothstep(shadowThreshold + 0.2, shadowThreshold - 0.2, luma);\nif (mask <= 0.001) return src;\nvec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0);\nfloat t = time * speed;\nvec2 v = p;\nfor (int i = 0; i < 5; i++) {\nif (float(i) > complexity) break;\nfloat c = cos(t * 0.2 + v.x * 2.5);\nfloat s = sin(t * 0.2 + v.y * 2.5);\nv = mat2(c, -s, s, c) * v;\nv = abs(v) / clamp(dot(v, v), 0.1, 1.5) - 0.4;\n}\nvec2 warp = uv + v * warpAmount * mask * 0.02;\nvec2 shift = v * chromaShift * mask * 0.02;\nfloat r = texture2D(tex, fract(warp + shift)).r;\nfloat g = texture2D(tex, fract(warp)).g;\nfloat b = texture2D(tex, fract(warp - shift)).b;\nvec3 warpedColor = vec3(r, g, b);\nvec3 tint = 0.5 + 0.5 * cos(t + v.xyx * 3.0 + vec3(0.0, 2.0, 4.0));\nwarpedColor = mix(warpedColor, warpedColor * tint * 1.5, mask * 0.4);\nreturn vec4(mix(src.rgb, warpedColor, mask), src.a);\n}",
