    code: "// NAME: Negative Difference Detector\nuniform float speed; // @min 0.1 @max 3.0 @default 1.0\nuniform float distortion; // @min 0.0 @max 5.0 @default 2.0\nuniform float zoom; // @min 0.01 @max 2.0 @default 0.25\nuniform bool invert; // @default true\nuniform float blackThreshold; // @min 0.0 @max 1.0 @default 0.05\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat t_mod = time * speed;\nvec2 p = uv - 0.5;\np.x *= (resolution.x / resolution.y);\np = p * zoom + vec2(sin(t_mod * 0.3), cos(t_mod * 0.4)) * 0.3;\nfloat c = cos(t_mod * 0.2);\nfloat s = sin(t_mod * 0.2);\nmat2 rot = mat2(c, -s, s, c);\nvec2 offset = vec2(0.15, -0.08) - (0.5 + distortion * 0.1);\nfor(int i = 0; i < 3; i++) {\np = rot * (p / clamp(dot(p, p), 0.1, 2.0) + offset);\n}\nvec4 distortedTex = texture2D(tex, fract(uv + p * (0.01 * distortion)));\nvec3 diff = abs(source.rgb - distortedTex.rgb);\nif (invert) {\ndiff = 1.0 - diff;\n}\nfloat brightness = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nif (brightness < blackThreshold) {\ndiff = vec3(0.0);\n}\nreturn vec4(diff, source.a);\n}",
