    code: "// NAME: Bipolar Depth & Dark Blob\nuniform float speed; // @min -10.0 @max 10.0 @default 5.0\nuniform float contrast; // @min 1.0 @max 5.0 @default 1.5\nuniform float depth; // @min 0.1 @max 5.0 @default 1.5\nuniform float blobSize; // @min 0.1 @max 1.0 @default 0.35\nuniform float blobDistort; // @min 0.0 @max 3.0 @default 1.5\nvec3 hsv2rgb(vec3 c) {\nvec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);\nvec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);\nreturn c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);\n}\nvec3 calcLight(vec3 lightPos, vec3 lightCol, vec3 normal, vec3 fragPos, vec3 viewDir) {\nvec3 lightDir = normalize(lightPos - fragPos);\nfloat diff = max(dot(normal, lightDir), 0.0);\nvec3 reflectDir = reflect(-lightDir, normal);\nfloat spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);\nfloat dist = length(lightPos - fragPos);\nreturn lightCol * (diff * 0.8 + spec * 1.2) / (1.0 + 2.0 * dist * dist);\n}\nvec3 getSceneLighting(vec3 normal, vec3 fragPos, vec3 viewDir, float time, float speed) {\nvec3 lighting = vec3(0.0);\nfor(int i = 0; i < 5; i++) {\nfloat fi = float(i);\nvec3 lPos = vec3(\nsin(time * speed * (0.15 + fi * 0.05) + fi * 2.1) * (0.5 + fi * 0.1),\ncos(time * speed * (0.18 - fi * 0.03) + fi * 1.3) * (0.5 + fi * 0.1),\n0.1 + sin(time * speed * 0.3 + fi * 1.7) * 0.2 + fi * 0.1\n);\nvec3 lCol = hsv2rgb(vec3(time * 0.05 + fi * 0.3, 0.3, 1.0));\nlighting += calcLight(lPos, lCol, normal, fragPos, viewDir);\n}\nreturn lighting;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec2 blobPos = vec2(0.5) + vec2(sin(time * 0.82), cos(time * 0.61)) * 0.3;\nvec2 dir = uv - blobPos;\nfloat dist = length(dir);\nfloat blobEffect = smoothstep(blobSize, 0.0, dist);\nvec2 baseUv = uv + dir * blobEffect * blobDistort;\nvec2 off = 1.0 / resolution;\nfloat t00 = texture2D(tex, baseUv + vec2(-off.x, -off.y)).r;\nfloat t10 = texture2D(tex, baseUv + vec2( 0.0, -off.y)).r;\nfloat t20 = texture2D(tex, baseUv + vec2( off.x, -off.y)).r;\nfloat t01 = texture2D(tex, baseUv + vec2(-off.x, 0.0)).r;\nfloat t21 = texture2D(tex, baseUv + vec2( off.x, 0.0)).r;\nfloat t02 = texture2D(tex, baseUv + vec2(-off.x, off.y)).r;\nfloat t12 = texture2D(tex, baseUv + vec2( 0.0, off.y)).r;\nfloat t22 = texture2D(tex, baseUv + vec2( off.x, off.y)).r;\nfloat gx = (t00 + 2.0 * t01 + t02) - (t20 + 2.0 * t21 + t22);\nfloat gy = (t00 + 2.0 * t10 + t20) - (t02 + 2.0 * t12 + t22);\nvec3 initialNormal = normalize(vec3(gx, gy, 1.0 / depth));\nvec3 fragPos = vec3(baseUv * 2.0 - 1.0, 0.0);\nvec3 viewDir = vec3(0.0, 0.0, 1.0);\nvec3 initialLighting = getSceneLighting(initialNormal, fragPos, viewDir, time, speed);\nfloat illum = dot(initialLighting, vec3(0.333));\nfloat depthMod = (illum - 0.35) * 20.0;\nvec3 normal = normalize(vec3(gx * depthMod, gy * depthMod, 1.0 / depth));\nvec3 lighting = getSceneLighting(normal, fragPos, viewDir, time, speed);\nvec2 offsetUv = baseUv - vec2(gx, gy) * depthMod * 0.002;\nvec4 texColor = texture2D(tex, offsetUv);\nvec3 finalColor = texColor.rgb * lighting * contrast;\nfinalColor *= mix(1.0, 0.05, blobEffect);\nreturn vec4(clamp(finalColor, 0.0, 1.0), texColor.a);\n}",
