    code: "// NAME: Reflective Disco CA\nuniform float pixelSize; // @min 2.0 @max 64.0 @default 16.0\nuniform float speed; // @min 0.0 @max 5.0 @default 2.0\nuniform vec3 waterColor; // @default 0.1,0.4,0.9\nuniform float threshold; // @min 0.0 @max 1.0 @default 0.05\nuniform float reflectivity; // @min 0.0 @max 5.0 @default 1.5\nuniform float gridOffsetX; // @min -1.0 @max 1.0 @default 0.0\nuniform float gridOffsetY; // @min -1.0 @max 1.0 @default 0.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat intensity = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nvec2 baseGrid = resolution / pixelSize;\nvec2 grid = baseGrid * intensity + 4.0;\nvec2 gridUv = uv + vec2(gridOffsetX, gridOffsetY);\nvec2 cellUv = floor(gridUv * grid) / grid;\nfloat t = time * speed;\nfloat n = node_noise(cellUv * 5.0 + vec2(t * 0.2, t * 0.5));\nn += node_noise(cellUv * 10.0 - vec2(t * 0.3, 0.0)) * 0.5;\nfloat states = 4.0;\nfloat caState = floor(n * states) / states;\nvec3 colorized = mix(source.rgb, waterColor * 1.5, caState * 0.7);\nvec2 localUv = fract(gridUv * grid);\nvec2 centerDist = localUv - 0.5;\nvec2 tilt = vec2(node_noise(cellUv * 20.0), node_noise(cellUv * 20.0 + 5.0)) * 2.0 - 1.0;\nvec3 normal = normalize(vec3(tilt * 0.8 + centerDist * 0.2, 1.0));\nvec3 lightPos = vec3(sin(t * 0.5), cos(t * 0.5), 1.0);\nvec3 lightDir = normalize(lightPos - vec3(uv * 2.0 - 1.0, 0.0));\nvec3 viewDir = vec3(0.0, 0.0, 1.0);\nvec3 halfVector = normalize(lightDir + viewDir);\nfloat spec = pow(max(dot(normal, halfVector), 0.0), 16.0) * reflectivity;\ncolorized += vec3(spec);\nfloat border = step(0.05, localUv.x) * step(0.05, localUv.y);\ncolorized *= mix(0.4, 1.0, border);\nfloat mask = step(threshold, intensity);\nvec3 finalColor = mix(source.rgb, colorized, mask);\nreturn vec4(finalColor, source.a);\n}",
