    code: "// NAME: Tentacle Spine Animated Mandala\nuniform float scale; // @min 5.0 @max 100.0 @default 25.0\nuniform float thickness; // @min 0.01 @max 0.4 @default 0.15\nuniform float speed; // @min 0.0 @max 5.0 @default 1.0\nuniform vec3 mazeColor; // @default 1.0,1.0,1.0\nuniform float morphAmount; // @min 0.0 @max 1.0 @default 0.3\nuniform float threshold; // @min 0.0 @max 1.0 @default 0.05\nuniform float mandalaGrid; // @min 1.0 @max 10.0 @default 2.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat intensity = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nif (intensity <= threshold) {\nreturn source;\n}\nvec2 distortedUV = uv;\ndistortedUV.y -= intensity * morphAmount;\ndistortedUV.x += (uv.x - 0.5) * 2.0 * intensity * morphAmount * 0.2;\nvec2 aspect = vec2(resolution.x / resolution.y, 1.0);\nvec2 baseUV = distortedUV * aspect;\nvec2 macroUV = baseUV * mandalaGrid;\nmacroUV.x += time * speed * 0.1;\nmacroUV.y += time * speed * 0.15;\nvec2 macroID = floor(macroUV);\nvec2 macroGV = fract(macroUV) - 0.5;\nfloat rndFolds = node_rand(macroID);\nfloat folds = 4.0 + floor(rndFolds * 4.0) * 2.0;\nfloat r = length(macroGV);\nfloat a = atan(macroGV.y, macroGV.x);\nfloat sector = 6.2831853 / folds;\na = mod(a, sector);\na = abs(a - sector / 2.0);\nvec2 foldedUV = r * vec2(cos(a), sin(a));\nvec2 p = foldedUV * scale;\np.y += time * speed;\np.x += time * speed * 0.5;\nvec2 id = floor(p);\nvec2 gv = fract(p) - 0.5;\nfloat rnd = node_rand(id);\nfloat flip = (rnd < 0.5) ? -1.0 : 1.0;\ngv.x *= flip;\nvec2 c1 = vec2(-0.5, -0.5);\nvec2 c2 = vec2(0.5, 0.5);\nfloat d1 = length(gv - c1);\nfloat d2 = length(gv - c2);\nfloat dist1 = abs(d1 - 0.5);\nfloat dist2 = abs(d2 - 0.5);\nfloat dist = min(dist1, dist2);\nfloat currentThickness = thickness * (0.5 + intensity * 1.0);\nfloat aa = (scale * mandalaGrid) / resolution.y * 1.5;\nfloat profile = smoothstep(currentThickness, 0.0, dist);\nfloat mask = smoothstep(currentThickness + aa, currentThickness - aa, dist);\nvec2 dir = (dist1 < dist2) ? (gv - c1) / d1 * sign(d1 - 0.5) : (gv - c2) / d2 * sign(d2 - 0.5);\ndir.x *= flip;\nvec3 N = normalize(vec3(dir * sin(profile * 1.570796) * 1.5, cos(profile * 1.570796)));\nvec3 V = vec3(0.0, 0.0, 1.0);\nvec3 L = normalize(vec3(0.5, 0.8, 1.0));\nvec3 R = reflect(-V, N);\nfloat diff = max(dot(N, L), 0.0);\nfloat spec = pow(max(dot(R, L), 0.0), 50.0);\nfloat fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);\nvec2 refUV = fract(uv + N.xy * 0.2);\nvec3 env = texture2D(tex, refUV).rgb;\nvec3 oily = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + N.x * 3.0 + N.y * 4.0 + time);\nfloat normalizedDist = dist / max(currentThickness, 0.001);\nvec3 waveColor = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + normalizedDist * 15.0 - time * 8.0);\nvec3 currentMazeColor = mazeColor * waveColor;\nvec3 blobColor = mix(env * currentMazeColor, oily, fresnel * 0.7) * (diff * 0.8 + 0.2) + spec * 1.2;\nfloat shadow = smoothstep(currentThickness * 2.5, currentThickness, dist) * 0.7;\nvec3 finalColor = mix(source.rgb * (1.0 - shadow), blobColor, mask);\nreturn vec4(finalColor, source.a);\n}",
