    code: "// NAME: Fluid Color Shadow Morph Maze\nuniform float scale; // @min 5.0 @max 50.0 @default 20.0\nuniform float heightZ; // @min 0.0 @max 0.2 @default 0.1\nuniform float colorShift; // @min 0.0 @max 5.0 @default 1.0\nuniform float threshold; // @min 0.0 @max 1.0 @default 0.05\nuniform float lineWidth; // @min 0.01 @max 0.51 @default 0.51\nuniform float glossiness; // @min 10.0 @max 100.0 @default 50.0\nuniform float specular; // @min 0.0 @max 2.0 @default 1.0\nuniform vec3 glowColor; // @default 0.0,1.0,1.0\nuniform float glowSpeed; // @min 0.0 @max 10.0 @default 5.0\nuniform float morphAmount; // @min 0.0 @max 1.0 @default 0.5\nuniform float speed; // @min 0.1 @max 3.0 @default 0.5\nuniform vec3 tint; // @default 0.5,0.7,1.0\nfloat getMazeHeight(vec2 st) {\nvec2 id = floor(st);\nvec2 gv = fract(st) - 0.5;\nif (node_rand(id) < 0.5) {\ngv.x *= -1.0;\n}\nfloat d1 = length(gv - vec2(-0.5, -0.5));\nfloat d2 = length(gv - vec2(0.5, 0.5));\nfloat d = min(abs(d1 - 0.5), abs(d2 - 0.5));\nfloat h = 1.0 - (d / max(lineWidth, 0.001));\nreturn max(h, 0.0);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat brightness = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nfloat mask = smoothstep(threshold - 0.05, threshold + 0.05, brightness) * source.a;\nif (mask <= 0.0) {\nreturn source;\n}\nvec2 st = uv * scale;\nst.x *= resolution.x / resolution.y;\nvec2 dir = (uv - 0.5) * heightZ;\nfloat hitZ = 1.0;\nvec2 hitSt = st;\nfor(int i = 0; i < 40; i++) {\nfloat f = float(i) / 39.0;\nvec2 offsetSt = st - dir * f * scale;\nfloat h = getMazeHeight(offsetSt);\nif (h > (1.0 - f)) {\nhitZ = f;\nhitSt = offsetSt;\nbreak;\n}\n}\nvec3 finalColor = source.rgb;\nfloat shadowH = getMazeHeight(st - dir * scale);\nvec3 shadowColor = source.rgb;\nif (shadowH > 0.0) {\nshadowColor *= mix(1.0, 0.3, shadowH);\n}\nif (hitZ < 1.0) {\nvec2 q = hitSt * 0.5;\nfloat t = time * speed;\nfloat w = 0.0;\nfor (int i = 0; i < 4; i++) {\nfloat c = cos(0.73);\nfloat s = sin(0.73);\nq = mat2(c, -s, s, c) * q * 1.4;\nq += vec2(sin(q.y + t), cos(q.x - t)) * 0.6;\nw += sin(q.x + q.y);\n}\nvec3 mazeCol = 0.5 + 0.5 * cos(w * 1.5 + tint * colorShift * 5.0 + vec3(0.0, 2.0, 4.0));\nvec2 eps = vec2(0.02, 0.0);\nfloat hx = getMazeHeight(hitSt + eps.xy) - getMazeHeight(hitSt - eps.xy);\nfloat hy = getMazeHeight(hitSt + eps.yx) - getMazeHeight(hitSt - eps.yx);\nvec3 normal = normalize(vec3(-hx, -hy, 0.2));\nvec3 lightRight = normalize(vec3(1.0, 0.5, 0.8));\nvec3 lightLeft = normalize(vec3(-1.0, 0.5, 0.8));\nvec3 viewDir = normalize(vec3(0.0, 0.0, 1.0));\nfloat diffRight = max(dot(normal, lightRight), 0.0);\nfloat diffLeft = max(dot(normal, lightLeft), 0.0);\nvec3 halfRight = normalize(lightRight + viewDir);\nvec3 halfLeft = normalize(lightLeft + viewDir);\nfloat specR = pow(max(dot(normal, halfRight), 0.0), glossiness);\nfloat specL = pow(max(dot(normal, halfLeft), 0.0), glossiness);\nvec3 colorRight = vec3(1.0, 0.6, 0.3) * diffRight + vec3(1.0) * specR * specular;\nvec3 colorLeft = vec3(0.3, 0.6, 1.0) * diffLeft + vec3(1.0) * specL * specular;\nvec3 lighting = colorRight + colorLeft + vec3(0.3);\nfloat shade = 1.0 - hitZ * 0.8;\nvec3 surfaceColor = mix(source.rgb, mazeCol * lighting * shade, 0.95);\nfloat h_hit = getMazeHeight(hitSt);\nfloat topMask = smoothstep(0.85, 1.0, h_hit);\nfloat movingPulse = sin(uv.x * 10.0 + uv.y * 10.0 - time * glowSpeed) * 0.5 + 0.5;\nmovingPulse = pow(movingPulse, 4.0);\nvec3 glow = glowColor * topMask * movingPulse * 2.5;\nsurfaceColor += glow;\nfinalColor = mix(shadowColor, surfaceColor, morphAmount);\n} else {\nfinalColor = shadowColor;\n}\nfinalColor = mix(source.rgb, finalColor, mask);\nreturn vec4(finalColor, source.a);\n}",
