    code: "// NAME: Glowing Radial Dots\nuniform float scale; // @min 5.0 @max 100.0 @default 25.0\nuniform float centerScale; // @min 0.0 @max 10.0 @default 2.0\nuniform float thickness; // @min 0.01 @max 1.0 @default 0.6\nuniform float speed; // @min 0.0 @max 5.0 @default 1.0\nuniform float zoomSpeed; // @min 0.0 @max 5.0 @default 1.0\nuniform float palette; // @min 0.0 @max 1.0 @default 0.5\nuniform float morphAmount; // @min 0.0 @max 1.0 @default 0.3\nuniform float threshold; // @min 0.0 @max 1.0 @default 0.05\nuniform float mandalaGrid; // @min 1.0 @max 10.0 @default 2.0\nuniform float glow; // @min 0.0 @max 5.0 @default 2.5\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 originalSource = texture2D(tex, uv);\nfloat origIntensity = dot(originalSource.rgb, vec3(0.299, 0.587, 0.114));\nif (origIntensity <= threshold) {\nreturn originalSource;\n}\nvec2 px = 1.0 / resolution;\nvec4 source = originalSource;\nvec4 n_tex = texture2D(tex, uv + vec2(0.0, px.y));\nvec4 s_tex = texture2D(tex, uv + vec2(0.0, -px.y));\nvec4 e_tex = texture2D(tex, uv + vec2(px.x, 0.0));\nvec4 w_tex = texture2D(tex, uv + vec2(-px.x, 0.0));\nvec4 minN = min(min(n_tex, s_tex), min(e_tex, w_tex));\nvec4 maxN = max(max(n_tex, s_tex), max(e_tex, w_tex));\nsource = clamp(source, minN, maxN);\nvec3 invertedRGB = 1.0 - source.rgb;\nfloat morphIntensity = dot(invertedRGB, vec3(0.299, 0.587, 0.114));\nvec2 distortedUV = uv;\ndistortedUV.y -= morphIntensity * morphAmount;\ndistortedUV.x += (uv.x - 0.5) * 2.0 * morphIntensity * morphAmount * 0.2;\nvec2 p = distortedUV - 0.5;\np.x *= resolution.x / resolution.y;\nfloat r = max(length(p), 0.001);\nfloat a = atan(p.y, p.x);\nfloat logR = log(r) - time * zoomSpeed;\nfloat gridInt = max(1.0, floor(mandalaGrid));\nvec2 baseUV = vec2((a / 6.2831853) * gridInt, logR * centerScale);\nvec2 scaledUV = baseUV * scale;\nvec2 grid = fract(scaledUV) - 0.5;\nvec2 cellId = floor(scaledUV);\nfloat dist = length(grid);\nfloat aa = 0.02 + 0.1 * smoothstep(0.5, 0.0, r);\nfloat pattern = smoothstep(thickness + aa, thickness - aa, dist);\nfloat glowMask = smoothstep(thickness + 0.4, 0.0, dist);\nfloat noiseVal = node_noise(cellId * 0.15);\nfloat radialMix = sin(dist * 25.0 - time * speed * 8.0 + noiseVal * 6.28) * 0.5 + 0.5;\nvec3 dotColor = 0.5 + 0.5 * cos(6.28318 * (radialMix + palette + vec3(0.0, 0.33, 0.67)));\nvec3 baseImg = source.rgb * 0.2;\nvec3 col = mix(baseImg, dotColor * 1.5, pattern * morphIntensity);\ncol += dotColor * glowMask * morphIntensity * glow;\nreturn vec4(col, source.a);\n}",
