    code: "// NAME: DMT Entity Hall\nuniform float speed; // @min 0.1 @max 5.0 @default 1.0\nuniform float zoom; // @min 0.5 @max 5.0 @default 2.5\nuniform float breakthrough; // @min 0.0 @max 1.0 @default 0.0\nuniform float warp; // @min 0.0 @max 5.0 @default 1.0\nuniform float relief; // @min 0.0 @max 2.0 @default 0.8\nuniform float surfaceScale; // @min 0.1 @max 10.0 @default 3.0\nuniform float snakeWobble; // @min 0.0 @max 3.0 @default 0.8\nuniform float snakeSpeed; // @min 0.0 @max 10.0 @default 3.0\nuniform float colorShift; // @min 0.0 @max 1.0 @default 0.0\nuniform float glowIntensity; // @min 0.0 @max 4.0 @default 1.5\nuniform float threshold; // @min 0.0 @max 1.0 @default 0.05\nmat2 rot(float a) {\nfloat s = sin(a), c = cos(a);\nreturn mat2(c, -s, s, c);\n}\nfloat smin(float a, float b, float k) {\nfloat h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\nreturn mix(b, a, h) - k * h * (1.0 - h);\n}\nvec3 palette(float t, float bt, float shift) {\nvec3 a = vec3(0.5, 0.5, 0.5);\nvec3 b = vec3(0.5, 0.5, 0.5);\nvec3 c = vec3(1.0, 1.0, 1.0);\nvec3 d = vec3(0.26, 0.41, 0.55) + (shift * 0.5) + (bt * 0.5);\nreturn pow(a + b * cos(6.28318 * (c * t + d)), vec3(1.5));\n}\nvec4 fractalSurface(vec3 p, float time, float bt, float sScale) {\nfloat scale = (sScale * 0.4) + (bt * 2.5);\nvec3 z = p * scale;\nfloat orbit = 100.0;\nfloat acc = 0.0;\nfloat t_anim = time * (0.04 + bt * 0.12);\nfor(int i = 0; i < 6; i++) {\nz = abs(z + 0.05) - 0.6;\nz.xy *= rot(0.785 + t_anim * float(i+1));\nz.yz *= rot(0.2 * t_anim);\nfloat r2 = dot(z, z);\nz *= clamp(1.3 / r2, 0.4, 1.6);\norbit = min(orbit, r2);\nacc += r2 * 0.12;\n}\nreturn vec4(acc, clamp(orbit * 2.2, 0.0, 1.0), orbit, scale);\n}\nfloat sdSerpent(vec3 p, float i, float time, float bt, float wobble, float sSpeed) {\nfloat ang = i * 1.57;\np.xy -= vec2(cos(ang), sin(ang)) * (2.6 + i * 0.2);\nfloat t = time * sSpeed;\nfloat w = wobble + bt * 2.5;\np.x += sin(p.z * 0.45 + t) * w;\np.y += cos(p.z * 0.25 + t * 0.8) * (w * 0.5);\nfloat scales = sin(p.z * 22.0) * 0.025;\nreturn length(p.xy) - (0.32 + scales);\n}\nfloat sdFloorSerpent(vec3 p, float time, float bt, float wobble, float sSpeed, float yOff, float phase) {\nfloat t = time * sSpeed + phase;\nfloat w = (wobble + bt * 2.0) * 1.2;\np.y += yOff;\np.x += sin(p.z * 0.6 + t) * w;\nfloat scales = cos(p.z * 25.0) * 0.02;\nreturn length(p.xy) - (0.28 + scales);\n}\nfloat scene(vec3 p, float time, float bt, float rlf, float wrp, float sScale, float wobble, float sSpeed, inout float g, inout float sg) {\nfloat d = 1.4 - abs(p.y);\nvec3 q = p; q.x = abs(q.x);\nvec3 q1 = q; q1.x -= 1.8; q1.z = mod(p.z, 3.5) - 1.75;\nfloat col1 = length(q1.xz) - (0.18 + 0.12 * pow(abs(p.y), 4.0));\nvec3 q2 = q; q2.x -= 4.8; q2.z = mod(p.z + 1.75, 3.5) - 1.75;\nfloat col2 = length(q2.xz) - (0.22 + 0.15 * pow(abs(p.y), 3.0));\nd = smin(d, col1, 0.45);\nd = smin(d, col2, 0.45);\nvec4 frac = fractalSurface(p, time, bt, sScale);\nd -= (1.0 - frac.y) * 0.18 * rlf;\nfloat sDist = 100.0;\nfor(int i = 0; i < 4; i++) {\nsDist = smin(sDist, sdSerpent(p, float(i), time, bt, wobble, sSpeed), 0.3);\n}\nfloat fDist1 = sdFloorSerpent(p, time, bt, wobble, sSpeed, 1.15, 0.0);\nfloat fDist2 = sdFloorSerpent(p, time, bt, wobble, sSpeed, 1.35, 3.1415);\nsDist = smin(sDist, fDist1, 0.25);\nsDist = smin(sDist, fDist2, 0.25);\nsg += (0.012 + bt * 0.045) / (0.025 + abs(sDist));\nd = smin(d, sDist, 0.18);\nd += sin(p.x * 9.0) * cos(p.y * 9.0) * sin(p.z * 4.5) * 0.006 * (wrp + bt * 7.0);\ng += 0.006 / (0.018 + abs(d));\nreturn d;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat val = length(source.rgb);\nfloat mask = clamp((val - threshold) * 20.0, 0.0, 1.0);\nif (mask <= 0.0) return source;\nvec2 q = (uv - 0.5) * 2.0;\nq.x *= resolution.x / resolution.y;\nfloat bt = breakthrough;\nfloat t = time * speed;\nfloat pos = t * (4.0 + bt * 12.0);\nfloat glow = 0.0, sGlow = 0.0;\nvec3 ro = vec3(0.0, 0.0, pos);\nvec3 rd = normalize(vec3(q, zoom * (1.0 - bt * 0.88) + 0.12));\nfloat dO = 0.0;\nfor(int i = 0; i < 64; i++) {\nfloat ds = scene(ro + rd * dO, t, bt, relief, warp, surfaceScale, snakeWobble, snakeSpeed, glow, sGlow);\ndO += ds;\nif(dO > 45.0 || abs(ds) < 0.003) break;\n}\nvec3 p = ro + rd * dO;\nvec4 frac = fractalSurface(p, t, bt, surfaceScale);\nvec3 c1 = palette(frac.x * 0.22 + t * 0.12, bt, colorShift);\nvec3 c2 = palette(frac.z * 3.2 - t * 0.06, bt, colorShift + 0.5);\nvec3 col = mix(c1, c2, sin(frac.x * 2.2) * 0.5 + 0.5);\ncol *= smoothstep(0.05, 1.4, frac.y + 0.4);\ncol *= clamp(1.0 - dO / 45.0, 0.0, 1.0);\nfloat effGlow = glowIntensity + bt * 4.0;\ncol += glow * 0.015 * palette(t * 0.1 + p.z * 0.04, bt, 0.1) * effGlow;\ncol += sGlow * 0.03 * palette(t * 0.4 - p.z * 0.06, bt, 0.8) * effGlow;\ncol = mix(col, vec3(1.0), pow(bt, 6.0) * (1.0 - exp(-0.01 * dO * dO)));\ncol = mix(col, vec3(1.0), smoothstep(0.96, 1.0, bt));\nvec3 effect = pow(col, vec3(1.1));\nfloat origGray = dot(source.rgb, vec3(0.299, 0.587, 0.114));\neffect *= origGray;\nvec3 finalRGB = mix(source.rgb, effect, mask);\nreturn vec4(finalRGB, source.a);\n}",
