    code: "// NAME: Transparent Lava Bubbles\nuniform float timeScale; // @default 1.0\nuniform vec3 lavaColor; // @default 1.0,0.3,0.0\nuniform float blackThreshold; // @min 0.0 @max 1.0 @default 0.0\nuniform float morphIntensity; // @min 0.0 @max 5.0 @default 1.0\nuniform float refraction; // @min 0.0 @max 0.5 @default 0.1\nuniform float luminosity; // @min 0.0 @max 3.0 @default 1.0\nuniform float contrast; // @min 0.0 @max 3.0 @default 1.0\nuniform float bubbleOpacity; // @min 0.0 @max 1.0 @default 0.4\nfloat smin(float a, float b, float k) {\nfloat h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\nreturn mix(b, a, h) - k * h * (1.0 - h);\n}\nfloat map(vec3 p, float t, float lum) {\nfloat d = p.y + 3.0;\nd = smin(d, 3.0 - p.y, 1.0);\nvec3 q = p;\nq.x = mod(q.x + 2.5, 5.0) - 2.5;\nfor(int i = 0; i < 6; i++) {\nfloat fi = float(i);\nvec3 pos = vec3(\nsin(t * 0.7 + fi * 2.1) * 1.2,\nsin(t * 0.4 + fi * 1.7) * 2.8,\ncos(t * 0.6 + fi * 1.3) * 0.8\n);\nfloat r = 0.6 + lum * morphIntensity * 0.3 + sin(fi) * 0.2;\nd = smin(d, length(q - pos) - r, 1.2);\n}\nreturn d;\n}\nvec3 calcNormal(vec3 p, float t, float lum) {\nvec2 e = vec2(0.01, 0.0);\nreturn normalize(vec3(\nmap(p+e.xyy, t, lum) - map(p-e.xyy, t, lum),\nmap(p+e.yxy, t, lum) - map(p-e.yxy, t, lum),\nmap(p+e.yyx, t, lum) - map(p-e.yyx, t, lum)\n));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 bg = texture2D(tex, uv);\nfloat bgLum = dot(bg.rgb, vec3(0.299, 0.587, 0.114));\nvec3 finalColor = bg.rgb;\nif (bgLum < blackThreshold) {\nfinalColor = vec3(0.0);\n} else {\nvec2 p_uv = (uv - 0.5) * 2.0;\np_uv.x *= resolution.x / resolution.y;\nvec3 ray = normalize(vec3(p_uv, 1.0));\nvec3 camPos = vec3(0.0, 0.0, -4.0);\nvec3 pos = camPos;\nfloat t = time * timeScale;\nfloat dist = 0.0;\nfor(int i = 0; i < 60; i++) {\ndist = map(pos, t, bgLum);\nif(dist < 0.005 || pos.z > 10.0) break;\npos += ray * dist;\n}\nif (dist < 0.005) {\nvec3 n = calcNormal(pos, t, bgLum);\nvec3 l = normalize(vec3(0.5, 1.0, -1.0));\nvec2 distortedUV = uv + n.xy * refraction;\nvec3 distortedBg = texture2D(tex, distortedUV).rgb;\nfloat spec = pow(max(dot(reflect(-l, n), -ray), 0.0), 32.0);\nfloat fresnel = pow(1.0 - max(dot(n, -ray), 0.0), 3.0);\nfloat mixFactor = clamp(bubbleOpacity + fresnel * 0.6, 0.0, 1.0);\nvec3 col = mix(distortedBg, lavaColor, mixFactor);\ncol += spec * 0.8;\nfloat distFromCam = length(pos - camPos);\nfloat alpha = 1.0 - smoothstep(4.0, 12.0, distFromCam);\nfinalColor = mix(bg.rgb, col, alpha);\n}\n}\nfinalColor = (finalColor - 0.5) * contrast + 0.5;\nfinalColor *= luminosity;\nreturn vec4(clamp(finalColor, 0.0, 1.0), 1.0);\n}",
