    code: "// NAME: Outward Spectrum Ripple\nuniform float speed; // @min 0.1 @max 5.0 @default 1.0\nuniform float range; // @min 1.0 @max 50.0 @default 15.0\nuniform float brightness; // @min 0.0 @max 10.0 @default 4.0\nuniform float ambient; // @min 0.0 @max 1.0 @default 0.2\nvec3 rgb2hsv(vec3 c) {\nvec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);\nvec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));\nvec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));\nfloat d = q.x - min(q.w, q.y);\nfloat e = 1.0e-10;\nreturn vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);\n}\nvec3 hsv2rgb(vec3 c) {\nvec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);\nvec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);\nreturn c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nvec2 aspect = vec2(resolution.x / resolution.y, 1.0);\nvec2 uv_aspect = uv * aspect;\nvec3 hsv = rgb2hsv(source.rgb);\nfloat pixel_hue = hsv.x;\nfloat pixel_sat = hsv.y;\nvec3 total_light = vec3(0.0);\nfor(int i = 0; i < 10; i++) {\nfloat fi = float(i);\nfloat target_hue = fi / 10.0;\nfloat hue_dist = abs(pixel_hue - target_hue);\nhue_dist = min(hue_dist, 1.0 - hue_dist);\nfloat hue_mask = smoothstep(0.15, 0.0, hue_dist) * smoothstep(0.05, 0.2, pixel_sat);\nvec2 l_pos = vec2(\nsin(time * speed + fi * 2.1) * 0.4 + 0.5,\ncos(time * speed * 0.8 + fi * 3.7) * 0.4 + 0.5\n);\nfloat dist = length(uv_aspect - l_pos * aspect);\nfloat attenuation = exp(-dist * dist * range);\nfloat color_shift = dist * 5.0 - time * speed * 2.0;\nvec3 l_color = hsv2rgb(vec3(fract(target_hue + color_shift), 1.0, 1.0));\ntotal_light += l_color * attenuation * hue_mask * brightness;\n}\nvec3 finalRGB = source.rgb * (ambient + total_light);\nreturn vec4(finalRGB, source.a);\n}",
