    code: "// NAME: 10x Reflective TD Leopard\nuniform float gridScale; // @min 1.0 @max 50.0 @default 20.0\nuniform float morphSpeed; // @min 0.0 @max 5.0 @default 1.0\nuniform float depthAmount; // @min 0.0 @max 1.0 @default 0.15\nuniform float hexSize; // @min 0.01 @max 0.5 @default 0.35\nuniform float threshold; // @min 0.0 @max 1.0 @default 0.2\nuniform float colorNoise; // @min 0.0 @max 20.0 @default 10.0\nuniform float leopardDist; // @min 0.0 @max 1.0 @default 0.25\nuniform float reflectAmount; // @min 0.0 @max 5.0 @default 2.0\nuniform float specAmount; // @min 0.0 @max 20.0 @default 10.0\nfloat hexDist(vec2 p) {\np = abs(p);\nreturn max(dot(p, vec2(0.8660254, 0.5)), p.y);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 texColor = texture2D(tex, uv);\nfloat depth = dot(texColor.rgb, vec3(0.299, 0.587, 0.114));\nif (depth < threshold) return vec4(0.0);\nvec2 morph = vec2(sin(time * morphSpeed + uv.y * 8.0), cos(time * morphSpeed + uv.x * 8.0)) * 0.03;\nvec2 distortedUV = uv + morph + (uv - 0.5) * depth * depthAmount * 2.0;\nvec2 r = vec2(1.0, 1.7320508);\nvec2 h = r * 0.5;\nvec2 scaledUV = distortedUV * gridScale;\nvec2 a = mod(scaledUV, r) - h;\nvec2 b = mod(scaledUV - h, r) - h;\nvec2 localUV = dot(a, a) < dot(b, b) ? a : b;\nvec2 id = scaledUV - localUV;\nfloat angle = depth * 6.28 + sin(time * morphSpeed + uv.x * 10.0 + uv.y * 10.0) * 1.5;\nfloat s = sin(angle), c = cos(angle);\nlocalUV = mat2(c, -s, s, c) * localUV;\nfloat spotNoise = node_noise(localUV * 8.0 + id * 3.0 + time * 0.5);\nfloat dist = hexDist(localUV) + (spotNoise - 0.5) * leopardDist;\nfloat outerEdge = smoothstep(hexSize, hexSize - 0.05, dist);\nfloat innerEdge = smoothstep(hexSize * 0.4, hexSize * 0.4 + 0.05, dist + (spotNoise - 0.5) * 0.1);\nfloat edge = outerEdge * innerEdge;\nvec3 normal = normalize(vec3(localUV.x, localUV.y, 0.15 - dist * 0.5));\nnormal.xy += (vec2(node_noise(uv * 15.0), node_noise(uv * 15.0 + 5.0)) - 0.5) * 0.2;\nnormal = normalize(normal);\nvec2 refUV = fract(uv + normal.xy * reflectAmount * 0.2 + time * 0.05);\nvec3 reflection = texture2D(tex, refUV).rgb;\nvec3 lightDir = normalize(vec3(sin(time), cos(time), 1.0));\nfloat spec = pow(max(dot(normal, lightDir), 0.0), 40.0) * specAmount;\nfloat n = node_noise(id * 0.2 + time * 0.2);\nfloat wavePhase = dist * 15.0 - time * 5.0 + n * colorNoise;\nvec3 lsdColor = 0.5 + 0.5 * cos(wavePhase + vec3(0.0, 2.094, 4.188));\nvec3 finalColor = mix(texColor.rgb * 0.1, lsdColor, edge);\nfinalColor += reflection * edge * reflectAmount;\nfinalColor += vec3(spec) * edge;\nreturn vec4(finalColor, texColor.a);\n}",
