    code: "// NAME: Psychedelic Morph Threshold\nuniform float morph_strength; // @min 0.01 @max 1.0 @default 0.15\nuniform float animation_speed; // @min 0.0 @max 10.0 @default 2.0\nuniform float speed; // @min 0.0 @max 10.0 @default 3.0\nuniform float color_shift; // @min 0.0 @max 5.0 @default 2.0\nuniform float threshold; // @min 0.0 @max 1.0 @default 0.05\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 original = texture2D(tex, uv);\nfloat depth = dot(original.rgb, vec3(0.299, 0.587, 0.114));\nfloat current_morph = mix(0.01, morph_strength, sin(time * animation_speed) * 0.5 + 0.5);\nfloat angle = depth * 62.83 + time * speed;\nvec2 offset = vec2(cos(angle), sin(angle)) * depth * current_morph;\noffset += vec2(sin(uv.y * 30.0 + time * speed), cos(uv.x * 30.0 - time * speed)) * (current_morph * 0.2);\nfloat r = texture2D(tex, uv + offset * 1.5).r;\nfloat g = texture2D(tex, uv + offset * 1.0).g;\nfloat b = texture2D(tex, uv + offset * 0.5).b;\nvec3 warped_color = vec3(r, g, b);\nvec3 psycho_color = 0.5 + 0.5 * cos(time * color_shift + warped_color * 15.0 + vec3(0.0, 2.09, 4.18));\nvec3 final_color = mix(warped_color, psycho_color, 0.8);\nfloat mask = step(threshold, depth);\nfinal_color *= mask;\nreturn vec4(final_color, original.a);\n}",
