    code: "// NAME: Liquid Mercury\nuniform float fluidity; // @min 0.0 @max 5.0 @default 1.5\nuniform float bump_strength; // @min 0.001 @max 0.05 @default 0.01\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec2 wave = vec2(sin(uv.y * 15.0 + time * fluidity), cos(uv.x * 15.0 + time * fluidity)) * 0.005;\nvec2 flow_uv = uv + wave;\nvec2 eps = 1.0 / resolution;\nfloat h0 = dot(texture2D(tex, flow_uv).rgb, vec3(0.299, 0.587, 0.114));\nfloat hx = dot(texture2D(tex, flow_uv + vec2(eps.x, 0.0)).rgb, vec3(0.299, 0.587, 0.114));\nfloat hy = dot(texture2D(tex, flow_uv + vec2(0.0, eps.y)).rgb, vec3(0.299, 0.587, 0.114));\nvec3 normal = normalize(vec3((hx - h0) / bump_strength, (hy - h0) / bump_strength, 1.0));\nvec3 view = vec3(0.0, 0.0, 1.0);\nvec3 ref = reflect(-view, normal);\nvec3 silver = vec3(0.65, 0.7, 0.75);\nvec3 lightDir = normalize(vec3(0.5, 1.0, 0.5));\nfloat spec = pow(max(dot(ref, lightDir), 0.0), 32.0);\nvec2 ref_uv = fract(uv + ref.xy * 0.15);\nfloat env_lum = dot(texture2D(tex, ref_uv).rgb, vec3(0.299, 0.587, 0.114));\nenv_lum = smoothstep(0.2, 0.8, env_lum);\nvec3 mercury = silver * (env_lum * 0.7 + 0.3) + vec3(spec);\nreturn vec4(mercury, 1.0);\n}",
