    code: "// NAME: Wide Pouring Water with Splash\nuniform vec3 waterColor; // @default 0.3,0.7,0.9\nuniform float speed; // @min 0.1 @max 3.0 @default 1.0\nuniform float waterMax; // @min 0.1 @max 5.0 @default 2.0\nuniform float cameraY; // @min -5.0 @max 5.0 @default 0.0\nfloat map(vec3 p, float time) {\nfloat phase = time * speed * 0.5;\nfloat nPhase = phase + node_noise(vec2(time * 0.3, 0.0)) * 2.0;\nfloat cycle = sin(nPhase);\nfloat pouringDir = cos(nPhase);\nfloat isPouring = smoothstep(-0.2, 0.2, pouringDir);\nfloat wRad = (0.12 - smoothstep(1.0, -2.0, p.y) * 0.04) * isPouring;\nfloat stream = length(p.xz) - wRad + mix(10.0, 0.0, isPouring);\nfloat turb = node_noise(vec2(p.y * 8.0 + time * 15.0 * speed, p.x * 8.0));\nstream += (turb - 0.5) * 0.06 * isPouring;\nstream += sin(p.y * 35.0 + time * 25.0 * speed) * 0.01 * isPouring;\nfloat waterLevel = -1.0 + cycle * waterMax;\nfloat surfNoise = node_noise(p.xz * 4.0 - time * speed * 1.5);\nfloat splashDist = length(vec3(p.x, p.y - waterLevel, p.z));\nfloat splashBump = smoothstep(1.2, 0.0, splashDist) * isPouring * node_noise(p.xz * 20.0 - time * 15.0) * 0.15;\nfloat surface = p.y - waterLevel + (surfNoise - 0.5) * 0.06 + sin(length(p.xz) * 10.0 - time * 8.0 * speed) * 0.02 - splashBump;\nfloat pool = max(surface, max(abs(p.x) - 20.0, abs(p.z) - 6.0));\nreturn min(stream, pool);\n}\nvec3 getNormal(vec3 p, float time) {\nvec2 e = vec2(0.01, 0.0);\nreturn normalize(vec3(\nmap(p + e.xyy, time) - map(p - e.xyy, time),\nmap(p + e.yxy, time) - map(p - e.yxy, time),\nmap(p + e.yyx, time) - map(p - e.yyx, time)\n));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 bg = texture2D(tex, uv);\nif(dot(bg.rgb, vec3(1.0)) < 0.001) {\nreturn bg;\n}\nvec2 p = (uv - 0.5) * 2.0;\np.x *= resolution.x / resolution.y;\np.y = -p.y;\nvec3 ro = vec3(0.0, cameraY, 3.0);\nvec3 rd = normalize(vec3(p, -1.5));\nfloat t = 0.0;\nfor(int i = 0; i < 70; i++) {\nvec3 pos = ro + rd * t;\nfloat d = map(pos, time);\nif(d < 0.001 || t > 15.0) break;\nt += d;\n}\nif(t < 15.0) {\nvec3 pos = ro + rd * t;\nvec3 n = getNormal(pos, time);\nvec3 l = normalize(vec3(1.0, 2.0, 1.0));\nfloat diff = max(dot(n, l), 0.0);\nfloat spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 50.0);\nvec2 refrUv = uv + n.xy * 0.06;\nvec4 refrColor = texture2D(tex, clamp(refrUv, 0.0, 1.0));\nfloat fresnel = pow(1.0 - max(dot(n, -rd), 0.0), 5.0);\nfloat alpha = mix(0.25, 0.9, fresnel);\nvec3 baseColor = mix(refrColor.rgb, refrColor.rgb * waterColor, 0.6);\nvec3 waterShading = waterColor * diff * 0.5 + spec * 2.0;\nvec3 col = mix(baseColor, waterShading, alpha);\nfloat phase = time * speed * 0.5;\nfloat nPhase = phase + node_noise(vec2(time * 0.3, 0.0)) * 2.0;\nfloat cycle = sin(nPhase);\nfloat isPouring = smoothstep(-0.2, 0.2, cos(nPhase));\nfloat waterLevel = -1.0 + cycle * waterMax;\nfloat splashDist = length(vec3(pos.x, pos.y - waterLevel, pos.z));\nfloat splashNoise = node_noise(pos.xz * 25.0 - time * 20.0);\nfloat splash = smoothstep(1.2, 0.0, splashDist) * isPouring * splashNoise;\ncol = mix(col, vec3(1.0), splash * 0.85);\ncol = mix(col, bg.rgb, smoothstep(5.0, 12.0, t));\nreturn vec4(col, bg.a);\n}\nreturn bg;\n}",
