    code: "// NAME: Psychedelic Truchet Gradient Stripes\nuniform float morphAmount; // @min 0.0 @max 1.0 @default 0.8\nuniform float width; // @min 0.01 @max 0.5 @default 0.02\nuniform float stripeFreq; // @min 1.0 @max 20.0 @default 8.0\nuniform float stripeSpeed; // @min 0.0 @max 10.0 @default 3.0\nfloat rand3(vec3 r) {\nreturn fract(sin(dot(r.xy, vec2(1.38984 * sin(r.z), 1.13233 * cos(r.z)))) * 653758.5453);\n}\nfloat truchetarc(vec3 pos, float morph) {\nfloat r = length(pos.xy);\nreturn pow(pow(abs(r - 0.5), 8.0) + pow(abs(pos.z - 0.5), 8.0), 0.125) - (width + morph * 0.25);\n}\nfloat truchetcell(vec3 pos, float morph) {\nreturn min(min(\ntruchetarc(pos, morph),\ntruchetarc(vec3(pos.z, 1.0 - pos.x, pos.y), morph)),\ntruchetarc(vec3(1.0 - pos.y, 1.0 - pos.z, pos.x), morph)\n);\n}\nfloat distfunc(vec3 pos, float morph) {\nvec3 cellpos = fract(pos);\nvec3 gridpos = floor(pos);\nfloat rnd = rand3(gridpos);\nif(rnd < 0.125) return truchetcell(vec3(cellpos.x, cellpos.y, cellpos.z), morph);\nif(rnd < 0.250) return truchetcell(vec3(cellpos.x, 1.0 - cellpos.y, cellpos.z), morph);\nif(rnd < 0.375) return truchetcell(vec3(1.0 - cellpos.x, cellpos.y, cellpos.z), morph);\nif(rnd < 0.500) return truchetcell(vec3(1.0 - cellpos.x, 1.0 - cellpos.y, cellpos.z), morph);\nif(rnd < 0.625) return truchetcell(vec3(cellpos.y, cellpos.x, 1.0 - cellpos.z), morph);\nif(rnd < 0.750) return truchetcell(vec3(cellpos.y, 1.0 - cellpos.x, 1.0 - cellpos.z), morph);\nif(rnd < 0.875) return truchetcell(vec3(1.0 - cellpos.y, cellpos.x, 1.0 - cellpos.z), morph);\nreturn truchetcell(vec3(1.0 - cellpos.y, 1.0 - cellpos.x, 1.0 - cellpos.z), morph);\n}\nvec3 gradient(vec3 pos, float morph) {\nconst float eps = 0.0001;\nfloat mid = distfunc(pos, morph);\nreturn vec3(\ndistfunc(pos + vec3(eps, 0.0, 0.0), morph) - mid,\ndistfunc(pos + vec3(0.0, eps, 0.0), morph) - mid,\ndistfunc(pos + vec3(0.0, 0.0, eps), morph) - mid\n);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nif (length(source.rgb) < 0.01 || source.a < 0.01) {\nreturn source;\n}\nfloat morph = dot(source.rgb, vec3(0.299, 0.587, 0.114)) * morphAmount;\nvec2 coords = (2.0 * (uv * resolution) - resolution) / length(resolution);\nfloat a = time / 3.0;\nmat3 m = mat3(\n0.0, 1.0, 0.0,\n-sin(a), 0.0, cos(a),\ncos(a), 0.0, sin(a)\n);\nm = m * m;\nm = m * m;\nvec3 ray_dir = m * normalize(vec3(2.0 * coords, -1.0 + dot(coords, coords)));\nfloat t = time / 3.0;\nconst float pi = 3.141592;\nvec3 ray_pos = vec3(\n2.0 * (sin(t + sin(2.0 * t) / 2.0) / 2.0 + 0.5),\n2.0 * (sin(t - sin(2.0 * t) / 2.0 - pi / 2.0) / 2.0 + 0.5),\n2.0 * ((-2.0 * (t - sin(4.0 * t) / 4.0) / pi) + 0.5 + 0.5)\n);\nfloat i_iter = 64.0;\nfor(int j = 0; j < 64; j++) {\nfloat dist = distfunc(ray_pos, morph);\nray_pos += dist * ray_dir;\nif(abs(dist) < 0.001) {\ni_iter = float(j);\nbreak;\n}\n}\nvec3 normal = normalize(gradient(ray_pos, morph));\nfloat ao = 1.0 - i_iter / 64.0;\nfloat what = pow(max(0.0, dot(normal, -ray_dir)), 2.0);\nvec3 phase = ray_pos * stripeFreq + time * stripeSpeed;\nvec3 col = 0.5 + 0.5 * cos(phase.zxy + vec3(0.0, 2.094, 4.188) + phase.x * 0.5);\nfloat blackStripe = 0.5 + 0.5 * sin(dot(normal, vec3(1.0, 1.2, 0.8)) * stripeFreq * 1.5 + time * stripeSpeed);\nblackStripe = smoothstep(0.1, 0.9, blackStripe);\ncol *= blackStripe;\ncol *= 0.8 + 0.2 * sin(ray_pos.z * stripeFreq * 2.0 - time * stripeSpeed * 2.0);\nvec3 finalColor = col * ao * what;\nreturn vec4(finalColor, source.a);\n}",
