    code: "// NAME: Glowing Morphed Grid\nuniform float gridScale; // @min 5.0 @max 50.0 @default 20.0\nuniform float edgeIntensity; // @min 0.0 @max 5.0 @default 2.0\nuniform float morphIntensity; // @min 0.0 @max 0.5 @default 0.15\nuniform float glowIntensity; // @min 0.0 @max 5.0 @default 2.0\nuniform vec3 themeColor; // @default 0.0,0.8,1.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 texColor = texture2D(tex, uv);\nvec2 texel = 1.0 / resolution;\nfloat c = dot(texColor.rgb, vec3(0.333));\nfloat r = dot(texture2D(tex, uv + vec2(texel.x, 0.0)).rgb, vec3(0.333));\nfloat u = dot(texture2D(tex, uv + vec2(0.0, texel.y)).rgb, vec3(0.333));\nfloat edge = abs(c - r) + abs(c - u);\nedge = clamp(edge * edgeIntensity * 15.0, 0.0, 1.0);\nvec2 morphOffset = vec2(sin(time * 0.5), cos(time * 0.5)) * c * morphIntensity;\nvec2 morphedUV = uv + morphOffset;\nvec2 gridUV = fract(morphedUV * gridScale);\nvec2 dist = abs(gridUV - 0.5);\nfloat core = max(smoothstep(0.47, 0.5, dist.x), smoothstep(0.47, 0.5, dist.y));\nfloat glow = max(pow(dist.x * 2.0, 4.0), pow(dist.y * 2.0, 4.0)) * glowIntensity;\nfloat gridEffect = clamp(core + glow, 0.0, 1.0);\nvec3 structureColor = themeColor * edge;\nvec3 gridOverlay = themeColor * gridEffect * (c + 0.2);\nvec3 finalColor = (texColor.rgb * 0.15) + structureColor + gridOverlay;\nreturn vec4(finalColor, texColor.a);\n}",
