    group: "Dots & Grids",
    description: "Imported from shadertoexport for Sculpture and Stage use.",
    code: "// NAME: Stretched Automata Depth Lines\nuniform float lightX; // @min 0.0 @max 1.0 @default 0.5\nuniform float lightY; // @min 0.0 @max 1.0 @default 0.5\nuniform float lightIntensity; // @min 0.0 @max 5.0 @default 1.0\nuniform vec3 lightColorTint; // @default 1.0,1.0,1.0\nuniform float stretch; // @min 0.1 @max 10.0 @default 3.0\nuniform float edgeStrength; // @min 0.0 @max 100.0 @default 50.0\nfloat hash(vec2 p) {\nreturn fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);\n}\nfloat smoothNoise(vec2 p) {\nvec2 i = floor(p);\nvec2 f = fract(p);\nvec2 u = f * f * (3.0 - 2.0 * f);\nreturn mix(mix(hash(i + vec2(0.0, 0.0)), hash(i + vec2(1.0, 0.0)), u.x),\nmix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 col = texture2D(tex, uv);\nif (col.r == 0.0 && col.g == 0.0 && col.b == 0.0) {\nreturn col;\n}\nfloat depth = col.r;\nvec2 eps = vec2(1.0 / resolution.x, 1.0 / resolution.y);\nfloat dx = texture2D(tex, uv + vec2(eps.x, 0.0)).r - texture2D(tex, uv - vec2(eps.x, 0.0)).r;\nfloat dy = texture2D(tex, uv + vec2(0.0, eps.y)).r - texture2D(tex, uv - vec2(0.0, eps.y)).r;\nvec3 normal = normalize(vec3(-dx * 50.0, -dy * 50.0, 1.0));\nfloat edge = length(vec2(dx, dy)) * edgeStrength;\nfloat depthLine = smoothstep(0.3, 0.8, edge);\nvec2 p = uv * 0.69;\np.x *= resolution.x / resolution.y;\np.y *= stretch;\nfloat activator = smoothNoise(p + time * 0.7);\nfloat inhibitor = smoothNoise(p * 0.5 - time * 0.35);\nfloat blob = smoothstep(-1.1, -0.9, activator - inhibitor * 0.1);\nfloat spatialVariation = smoothNoise(p * 0.3);\nfloat growthWave = mod(time * 1.75 * (0.4 + 0.6 * spatialVariation) - depth * 2.0 + spatialVariation * 4.0, 2.5);\nfloat activeCell = blob * smoothstep(0.0, 0.3, growthWave) * smoothstep(1.2, 0.8, growthWave);\nvec3 dynamicColor = vec3(0.5) + 0.5 * cos(6.28318 * (smoothNoise(p * 0.3 + time * 0.15) + vec3(0.0, 0.33, 0.67)));\nvec3 totalLight = vec3(0.0);\nvec3 surfPos = vec3(uv, depth * 0.05);\nfor(int i = 0; i < 5; i++) {\nfloat fi = float(i);\nvec3 lightPos = (i == 0) ? vec3(lightX, lightY, 0.15) : vec3(0.5 + 0.6 * sin(time * 0.8 + fi * 13.44), 0.5 + 0.6 * cos(time * 1.04 - fi * 11.3), 0.15);\nvec3 lColor = (i == 0) ? vec3(1.0) : 0.5 + 0.5 * cos(fi * 0.392 + vec3(0.0, 2.09, 4.18));\nvec3 lightVector = lightPos - surfPos;\nfloat dist = length(lightVector);\nvec3 lightDir = normalize(lightVector);\nfloat diff = max(dot(normal, lightDir), 0.0);\nfloat spec = pow(max(dot(normal, normalize(lightDir + vec3(0.0, 0.0, 1.0))), 0.0), 32.0);\nfloat atten = 1.0 / (1.0 + dist * dist * 20.0);\ntotalLight += lColor * (diff + spec) * atten * lightIntensity;\n}\nvec3 finalColor = col.rgb * totalLight * lightColorTint + activeCell * dynamicColor;\nfinalColor += vec3(depthLine);\nreturn vec4(finalColor, col.a);\n}",
