    code: "// NAME: Psytrance Morph\n#define MAX_STEPS 60\n#define MAX_DIST 10.0\n#define SURF_DIST 0.005\nuniform float morphAmount; // @min 0.0 @max 2.0 @default 1.0\nuniform float trailSpeed; // @min 0.0 @max 10.0 @default 5.0\nuniform float stripFrequency; // @min 0.1 @max 20.0 @default 6.0\nuniform float diffusionSpeed; // @min 0.1 @max 5.0 @default 1.5\nmat2 Rot(float a) {\nfloat s = sin(a), c = cos(a);\nreturn mat2(c, -s, s, c);\n}\nfloat GetDist(vec3 p, float time, float depth) {\nvec2 uv = p.xz;\nuv.x = abs(uv.x);\nfloat t = 12.0 + time;\nvec2 q = vec2(1.0, 0.0);\nfloat th = 0.4 * p.y - 0.6 * t;\nfloat morphFactor = mix(1.0, depth * 2.5, (sin(time * 1.5) * 0.5 + 0.5) * morphAmount);\nfloat m = 1.8 * morphFactor;\nfor (int i = 0; i < 4; i++) {\nuv -= m * q;\nth += 0.5 * p.y + 0.05 * t;\nuv = Rot(th) * uv;\nuv.x = abs(uv.x);\nm *= 0.03 * cos(8.0 * length(uv)) + 0.55;\n}\nreturn 0.5 * (length(uv) - 2.0 * m);\n}\nvec3 GetNormal(vec3 p, float time, float depth) {\nfloat d = GetDist(p, time, depth);\nvec2 e = vec2(0.01, 0.0);\nvec3 n = d - vec3(\nGetDist(p - e.xyy, time, depth),\nGetDist(p - e.yxy, time, depth),\nGetDist(p - e.yyx, time, depth));\nreturn normalize(n);\n}\nvec3 getPsyColor(float t) {\nvec3 a = vec3(0.5, 0.5, 0.5);\nvec3 b = vec3(0.5, 0.5, 0.5);\nvec3 c = vec3(1.0, 1.0, 1.0);\nvec3 d = vec3(0.0, 0.33, 0.67);\nt += sin(t * 15.0) * 0.05;\nvec3 col = a + b * cos(6.28318 * (c * t + d));\nreturn smoothstep(0.1, 0.9, col);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nif (length(source.rgb) < 0.05) return vec4(0.0, 0.0, 0.0, source.a);\nvec2 p_uv = (uv - 0.5) * 2.0;\np_uv.x *= resolution.x / resolution.y;\nfloat depth = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nvec3 ro = vec3(0.0, 3.0, -3.0);\nvec3 f = normalize(-ro);\nvec3 r = normalize(cross(vec3(0.0, 1.0, 0.0), f));\nvec3 rd = normalize(f + p_uv.x * r + p_uv.y * cross(f, r));\nfloat dO = 0.0;\nfor(int i = 0; i < MAX_STEPS; i++) {\nvec3 p = ro + rd * dO;\nfloat dS = GetDist(p, time, depth);\ndO += dS * 0.5;\nif(dO > MAX_DIST || abs(dS) < SURF_DIST) break;\n}\nvec3 col = vec3(0.0);\nif(dO < MAX_DIST) {\nvec3 p = ro + rd * dO;\nvec3 n = GetNormal(p, time, depth);\nvec3 l = normalize(vec3(1.0, 2.0, -2.0));\nfloat spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);\nfloat fresnel = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);\nfloat stripIndex = floor(p.y * stripFrequency * 0.5 + length(p.xz) * stripFrequency * 0.5);\nfloat dir = mod(stripIndex, 2.0) > 0.5 ? 1.0 : -1.0;\nfloat stripeVal = sin(p.y * stripFrequency + length(p.xz) * (stripFrequency * 1.333) - time * trailSpeed * dir);\nfloat stripe = smoothstep(0.85, 0.95, stripeVal);\nvec3 neonColor = getPsyColor(time * 1.5 + depth * 2.0 + length(p) * 0.3);\ncol = spec * 2.0 * neonColor;\ncol += neonColor * stripe * 4.0;\ncol += neonColor * fresnel * 2.0;\n}\nreturn vec4(col * smoothstep(0.05, 0.1, depth), source.a);\n}",
