    code: "// NAME: Symmetric Psychedelic Truchet\nuniform float morphAmount; // @min 0.0 @max 1.0 @default 0.8\nuniform float width; // @min 0.01 @max 0.5 @default 0.02\nuniform float stripeFreq; // @min 1.0 @max 20.0 @default 8.0\nuniform float stripeSpeed; // @min 0.0 @max 10.0 @default 3.0\nuniform float camRotSpeed; // @min 0.0 @max 5.0 @default 0.5\nuniform float camMoveSpeed; // @min 0.0 @max 5.0 @default 0.5\nfloat rand3(vec3 r) {\nreturn fract(sin(dot(r.xy, vec2(1.38984 * sin(r.z), 1.13233 * cos(r.z)))) * 653758.5453);\n}\nfloat truchetarc(vec3 pos, float morph) {\nfloat r = length(pos.xy);\nreturn pow(pow(abs(r - 0.5), 8.0) + pow(abs(pos.z - 0.5), 8.0), 0.125) - (width + morph * 0.25);\n}\nfloat truchetcell(vec3 pos, float morph) {\nreturn min(min(\ntruchetarc(pos, morph),\ntruchetarc(vec3(pos.z, 1.0 - pos.x, pos.y), morph)),\ntruchetarc(vec3(1.0 - pos.y, 1.0 - pos.z, pos.x), morph)\n);\n}\nfloat distfunc(vec3 pos, float morph) {\nvec3 c = fract(pos);\nfloat rnd = rand3(floor(pos));\nif(rnd < 0.125) return truchetcell(c, morph);\nif(rnd < 0.250) return truchetcell(vec3(c.x, 1.0 - c.y, c.z), morph);\nif(rnd < 0.375) return truchetcell(vec3(1.0 - c.x, c.y, c.z), morph);\nif(rnd < 0.500) return truchetcell(vec3(1.0 - c.x, 1.0 - c.y, c.z), morph);\nif(rnd < 0.625) return truchetcell(vec3(c.y, c.x, 1.0 - c.z), morph);\nif(rnd < 0.750) return truchetcell(vec3(c.y, 1.0 - c.x, 1.0 - c.z), morph);\nif(rnd < 0.875) return truchetcell(vec3(1.0 - c.y, c.x, 1.0 - c.z), morph);\nreturn truchetcell(vec3(1.0 - c.y, 1.0 - c.x, 1.0 - c.z), morph);\n}\nvec3 gradient(vec3 pos, float morph) {\nvec2 e = vec2(0.001, 0.0);\nfloat mid = distfunc(pos, morph);\nreturn vec3(\ndistfunc(pos + e.xyy, morph) - mid,\ndistfunc(pos + e.yxy, morph) - mid,\ndistfunc(pos + e.yyx, morph) - mid\n);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nif (length(source.rgb) < 0.01 || source.a < 0.01) return source;\nfloat morph = dot(source.rgb, vec3(0.299, 0.587, 0.114)) * morphAmount;\nvec2 symUv = uv;\nsymUv.x = abs(symUv.x - 0.5) + 0.5;\nvec2 coords = (2.0 * (symUv * resolution) - resolution) / length(resolution);\nfloat a = time * camRotSpeed;\nmat3 m = mat3(0.0, 1.0, 0.0, -sin(a), 0.0, cos(a), cos(a), 0.0, sin(a));\nm = m * m * m;\nvec3 ray_dir = m * normalize(vec3(2.0 * coords, -1.0 + dot(coords, coords)));\nvec3 ray_pos = vec3(0.0, 0.0, time * camMoveSpeed);\nfloat dist = 0.0;\nfor(int i = 0; i < 30; i++) {\ndist = distfunc(ray_pos, morph);\nray_pos += dist * ray_dir;\nif(abs(dist) < 0.001) break;\n}\nvec3 normal = normalize(gradient(ray_pos, morph));\nvec3 color = vec3(0.5) + 0.5 * cos(time + ray_pos.z * stripeFreq + vec3(0.0, 2.0, 4.0));\nfloat stripe = sin(ray_pos.z * stripeFreq - time * stripeSpeed);\ncolor *= smoothstep(-0.1, 0.1, stripe);\nfloat diff = max(dot(normal, normalize(vec3(1.0, 1.0, -1.0))), 0.0);\ncolor = color * diff * 0.8 + 0.2 * color;\nreturn vec4(mix(source.rgb, color, source.a), source.a);\n}",
