    code: "// NAME: Depth Morph Raymarch Smooth\n#define MAX_STEPS 200\n#define MAX_DIST 10.0\n#define SURF_DIST 0.001\nuniform float morphAmount; // @min 0.0 @max 2.0 @default 1.0\nmat2 Rot(float a) {\nfloat s = sin(a), c = cos(a);\nreturn mat2(c, -s, s, c);\n}\nfloat GetDist(vec3 p, float time, float depth) {\nvec2 uv = p.xz;\nuv.x = abs(uv.x);\nfloat t = 12.0 + time;\nvec2 q = vec2(1.0, 0.0);\nfloat th = 0.4 * p.y - 0.6 * t;\nfloat morphFactor = mix(1.0, depth * 2.5, (sin(time * 1.5) * 0.5 + 0.5) * morphAmount);\nfloat m = 1.8 * morphFactor;\nfor (int i = 0; i < 6; i++) {\nuv -= m * q;\nth += 0.5 * p.y + 0.05 * t;\nuv = Rot(th) * uv;\nuv.x = abs(uv.x);\nm *= 0.03 * cos(8.0 * length(uv)) + 0.55;\n}\nreturn 0.5 * (length(uv) - 2.0 * m);\n}\nfloat RayMarch(vec3 ro, vec3 rd, float time, float depth) {\nfloat dO = 0.0;\nfor(int i = 0; i < MAX_STEPS; i++) {\nvec3 p = ro + rd * dO;\nfloat dS = GetDist(p, time, depth);\ndO += dS * 0.4;\nif(dO > MAX_DIST || abs(dS) < SURF_DIST) break;\n}\nreturn dO;\n}\nvec3 GetNormal(vec3 p, float time, float depth) {\nfloat d = GetDist(p, time, depth);\nvec2 e = vec2(0.005, 0.0);\nvec3 n = d - vec3(\nGetDist(p - e.xyy, time, depth),\nGetDist(p - e.yxy, time, depth),\nGetDist(p - e.yyx, time, depth));\nreturn normalize(n);\n}\nvec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {\nvec3 f = normalize(l - p);\nvec3 r = normalize(cross(vec3(0.0, 1.0, 0.0), f));\nvec3 u = cross(f, r);\nvec3 c = f * z;\nvec3 i = c + uv.x * r + uv.y * u;\nreturn normalize(i);\n}\nvec3 pal(float t, vec3 a, vec3 b, vec3 c, vec3 d) {\nreturn a + b * cos(6.28318 * (c * t + d));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nif (dot(source.rgb, vec3(1.0)) < 0.01) {\nreturn vec4(0.0, 0.0, 0.0, source.a);\n}\nfloat depth = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nvec2 p_uv = (uv - 0.5) * (resolution / resolution.y);\nfloat r_cam = 5.5;\nfloat t_cam = 0.0;\nvec3 ro = vec3(r_cam * cos(t_cam), 0.1 * time, r_cam * sin(t_cam));\nvec3 rd = GetRayDir(p_uv, ro, vec3(0.0, 0.1 * time, 0.0), 2.0);\nfloat d = RayMarch(ro, rd, time, depth);\nvec3 col = vec3(0.0);\nif(d < MAX_DIST) {\nvec3 p = ro + rd * d;\nvec3 n = GetNormal(p, time, depth);\nvec3 ref = reflect(rd, n);\nfloat ambient = 0.3;\nfloat difPower = 0.4;\nfloat dif = max(dot(n, normalize(vec3(1.0, 2.0, 3.0))), 0.0);\ncol = vec3(dif * difPower + ambient);\nvec2 refUV = vec2(atan(ref.z, ref.x) / 6.2831853 + 0.5, asin(ref.y) / 3.1415926 + 0.5);\ncol *= texture2D(tex, refUV).rgb;\ncol *= 1.0 + ref.y;\ncol = clamp(col, 0.0, 1.0);\nvec3 e = vec3(1.0);\ncol *= pal(ref.y, e, e, e, vec3(0.3, 0.2, 0.2));\n}\nreturn vec4(col, source.a);\n}",
