    description: "Imported from shadertoexport for Stage use.",
    code: "// NAME: Psytrance Disco Room Vertical Bands\nuniform float intensity; // @min 0.0 @max 1.0 @default 1.0\nuniform float speed; // @min 0.0 @max 5.0 @default 1.0\nuniform float gridScale; // @min 5.0 @max 100.0 @default 30.0\nuniform float scale; // @min 1.0 @max 20.0 @default 4.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat depth = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nvec2 p = uv * 2.0 - 1.0;\nfloat t = time * speed;\nfloat zRoom = max(0.1, 1.5 - abs(p.x));\nvec2 uvRoom = vec2(p.y / zRoom, 1.0 / zRoom) + vec2(0.0, t);\nuvRoom += depth * 0.4 * vec2(sin(t + uvRoom.y * 2.0), cos(t + uvRoom.x * 2.0));\nvec2 fGrid = fract(uvRoom * gridScale);\nfloat gridLine = clamp(step(0.85, fGrid.x) + step(0.85, fGrid.y), 0.0, 1.0);\nvec3 roomColor = vec3(0.1, 1.0, 0.5) * gridLine * smoothstep(0.0, 1.5, zRoom);\nfloat dist = abs(p.x);\nfloat bandPhase = fract(dist * scale - t * 2.0);\nfloat bandAlpha = smoothstep(1.0, 0.0, dist) * smoothstep(0.7, 0.9, bandPhase) * (1.0 - bandPhase);\nvec3 bandColor = vec3(1.0, 0.2, 0.8) * bandAlpha * 3.0;\nvec3 psySource = source.rgb * vec3(\n0.6 + 0.5 * sin(t * 4.0 + depth * 10.0),\n0.6 + 0.5 * cos(t * 3.2 + depth * 12.0),\n0.6 + 0.5 * sin(t * 2.8 - depth * 8.0)\n);\nvec3 finalColor = mix(source.rgb, psySource + roomColor + bandColor, intensity);\nfloat isNotBlack = step(0.03, length(source.rgb));\nfinalColor *= isNotBlack;\nreturn vec4(finalColor, source.a);\n}",
