    description: "Imported from shadertoexport for Sculpture and Stage use.",
    code: "// NAME: Depth Morph Fractal Zones\nuniform float intensity; // @min 0.0 @max 1.0 @default 0.8\nuniform float speed; // @min 0.0 @max 2.0 @default 0.5\nuniform float blackThreshold; // @min 0.0 @max 1.0 @default 0.05\nuniform float morphAmount; // @min 0.0 @max 5.0 @default 1.5\nuniform float zoneScale; // @min 0.0 @max 1.0 @default 0.4\nmat2 rot(float a) {\nfloat c = cos(a), s = sin(a);\nreturn mat2(c, -s, s, c);\n}\nfloat map(vec3 p, float t) {\nfloat s = 1.0;\nvec3 offset = vec3(0.4) + zoneScale * vec3(sin(p.y * 2.5 + t), cos(p.z * 2.5), sin(p.x * 2.5 - t));\nfor(int i = 0; i < 5; i++) {\np = abs(p) - offset;\np.xy *= rot(t * 0.5 + 0.5);\np.xz *= rot(t * 0.3);\np *= 1.65;\ns *= 1.65;\n}\nreturn length(p) / s - 0.005;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat luma = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nfloat mask = smoothstep(blackThreshold * 0.5, blackThreshold + 0.01, luma);\nvec2 p = (uv - 0.5) * 2.0;\np.x *= resolution.x / (resolution.y + 0.0001);\nfloat t = time * speed + luma * morphAmount;\nvec3 ro = vec3(0.0, 0.0, -1.5 + luma * morphAmount * 0.5);\nvec3 rd = normalize(vec3(p, 1.0));\nfloat d = 0.0;\nfloat dist = 0.0;\nint steps = 0;\nvec3 pos = vec3(0.0);\nfor(int i = 0; i < 45; i++) {\npos = ro + rd * dist;\nd = map(pos, t);\nif(d < 0.001 || dist > 5.0) break;\ndist += d;\nsteps = i;\n}\nvec3 dynamicColor = 0.5 + 0.5 * cos(time * speed * 2.0 + pos.xyz * 2.0 + vec3(0.0, 2.0, 4.0));\nfloat stepRatio = float(steps) / 45.0;\nvec3 finalFractalColor = mix(vec3(0.05), dynamicColor, stepRatio * 2.0);\nfinalFractalColor = mix(finalFractalColor, dynamicColor * 1.5, pow(stepRatio, 2.0));\nfinalFractalColor += dynamicColor * (0.02 / (d + 0.01));\nfinalFractalColor *= exp(-dist * 0.5);\nvec3 finalColor = mix(source.rgb, finalFractalColor + source.rgb * finalFractalColor * 0.5, intensity * mask);\nreturn vec4(finalColor, source.a);\n}",
