    code: "// NAME: Metallic Plant Morph\nuniform float intensity; // @min 0.0 @max 1.0 @default 0.8\nuniform float plantSpeed; // @min 0.0 @max 2.0 @default 0.5\nuniform float metalSpeed; // @min -3.0 @max 3.0 @default 1.0\nuniform float frequency; // @min 1.0 @max 30.0 @default 10.0\nuniform float sharpness; // @min 1.0 @max 10.0 @default 4.0\nuniform vec3 tint; // @default 0.9,0.95,1.0\nuniform float blackThreshold; // @min 0.0 @max 1.0 @default 0.05\nuniform float morphAmount; // @min 0.0 @max 5.0 @default 1.5\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat luma = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nfloat mask = smoothstep(blackThreshold * 0.5, blackThreshold + 0.01, luma);\nfloat phase = luma * frequency - time * metalSpeed;\nfloat band1 = sin(phase * 6.28318) * 0.5 + 0.5;\nfloat band2 = sin(phase * 15.0 + 2.0) * 0.5 + 0.5;\nfloat metallic = pow(band1 * 0.8 + band2 * 0.2, sharpness);\nfloat highlight = smoothstep(0.7, 1.0, metallic);\nvec3 reflectionColor = mix(source.rgb * 0.5, tint, metallic) + highlight * tint;\nfloat t = time * plantSpeed;\nvec2 p = uv * 15.0 + luma * morphAmount;\nfloat plantPattern = sin(p.x + t) * cos(p.y - t);\nplantPattern = smoothstep(0.0, 1.0, abs(plantPattern));\nvec3 plantColor = source.rgb * tint * (plantPattern * 0.8 + 0.2);\nvec3 finalColor = mix(source.rgb, mix(reflectionColor, plantColor, 0.5), intensity * mask);\nreturn vec4(finalColor, source.a);\n}",
