    code: "// NAME: Hex Morph Depth 3D\nuniform float morph; // @min 0.0 @max 1.0 @default 0.5\nuniform float scale; // @min 1.0 @max 50.0 @default 20.0\nuniform float amount; // @min 0.0 @max 1.0 @default 1.0\nuniform float speed; // @min 0.0 @max 5.0 @default 1.0\nfloat HexDist(vec2 p) {\np = abs(p);\nfloat c = dot(p, normalize(vec2(1.0, 1.73)));\nc = max(c, p.x);\nreturn c;\n}\nvec4 HexCoords(vec2 uv) {\nvec2 r = vec2(1.0, 1.73);\nvec2 h = r * 0.5;\nvec2 a = mod(uv, r) - h;\nvec2 b = mod(uv - h, r) - h;\nvec2 gv = dot(a, a) < dot(b, b) ? a : b;\nfloat x = atan(gv.x, gv.y);\nfloat y = 0.5 - HexDist(gv);\nvec2 id = uv - gv;\nreturn vec4(x, y, id.x, id.y);\n}\nfloat random(vec2 st, float t) {\nreturn fract(sin(dot(st.xy, vec2(12.9898 * sin(t / 600.0), 78.233))) * 43758.5453123);\n}\nfloat noise(vec2 st, float t) {\nvec2 i = floor(st);\nvec2 f = fract(st);\nfloat a = random(i, t);\nfloat b = random(i + vec2(1.0, 0.0), t);\nfloat c = random(i + vec2(0.0, 1.0), t);\nfloat d = random(i + vec2(1.0, 1.0), t);\nvec2 u = f * f * (3.0 - 2.0 * f);\nreturn mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat t = time * speed;\nfloat depth = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nvec2 p = (uv - 0.5) * resolution / resolution.y;\np *= scale * mix(1.0, 1.0 - depth * 0.8, morph);\np += (uv - 0.5) * depth * morph * 3.0;\np.x = abs(p.x);\np.y = abs(p.y);\nfloat n1 = noise(p, t);\nfloat n2 = fract(sin(t * 100.0) * 43758.5453);\nvec4 hc = HexCoords(p * sin(n1));\nhc /= 0.5;\np *= sin(mix(n1, n2, cos(t) * 0.5 + n1));\nfloat c = smoothstep(0.01, 0.5, hc.y * cos(hc.z * hc.w + t) * 0.5 + 0.20);\nvec3 col = vec3(c);\ncol *= vec3(abs(sin(p.x + t)), abs(cos(hc.w * t / 200.0)), abs(sin(hc.z * t / 300.0)));\nfloat depthMorph = clamp(morph + (1.0 - depth) * 0.5 - 0.25, 0.0, 1.0);\nvec3 effectCol = mix(col, source.rgb, depthMorph);\nfloat isNonBlack = step(0.01, length(source.rgb));\nvec3 finalCol = mix(source.rgb, effectCol, isNonBlack * amount);\nreturn vec4(finalCol, source.a);\n}",
