    description: "Imported from shadertoexport for Sculpture and Stage use.",
    code: "// NAME: Pop Up Character\nuniform float intensity; // @min 0.0 @max 1.0 @default 0.8\nuniform float speed; // @min 0.0 @max 2.0 @default 1.0\nuniform float movement; // @min 0.0 @max 2.0 @default 1.0\nuniform vec3 manColor; // @default 0.9,0.8,0.8\nuniform vec3 bgColor; // @default 0.0,0.0,0.0\nfloat smin(float a, float b, float k) {\nfloat h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\nreturn mix(b, a, h) - k * h * (1.0 - h);\n}\nfloat sdCap(vec3 p, vec3 a, vec3 b, float r) {\nvec3 pa = p - a, ba = b - a;\nfloat h = clamp(dot(pa, ba) / (dot(ba, ba) + 0.0001), 0.0, 1.0);\nreturn length(pa - ba * h) - r;\n}\nfloat map(vec3 p, float t) {\nfloat phase = mod(t, 4.0);\np.y += 2.5 - (smoothstep(0.0, 0.8, phase) - smoothstep(2.0, 2.8, phase)) * 2.5;\np.y += sin(t * 2.0) * 0.05 * movement;\nfloat head = length(p - vec3(0.0, 0.3, 0.0)) - 0.2;\nfloat body = sdCap(p, vec3(0.0, 0.1, 0.0), vec3(0.0, -0.3, 0.0), 0.15);\nvec3 symP = vec3(abs(p.x), p.y, p.z);\nfloat swing = sin(t * 3.0) * 0.2 * sign(p.x + 0.001) * movement;\nfloat arms = sdCap(symP, vec3(0.16, 0.05, 0.0), vec3(0.3, -0.25, -swing), 0.04);\nfloat legs = sdCap(symP, vec3(0.08, -0.3, 0.0), vec3(0.08, -0.65, swing), 0.05);\nreturn smin(smin(smin(head, body, 0.05), arms, 0.05), legs, 0.05);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nvec2 p = (uv - 0.5) * 2.0;\np.x *= resolution.x / (resolution.y + 0.0001);\nfloat t = time * speed;\nvec3 ro = vec3(0.0, 0.0, -1.5);\nvec3 rd = normalize(vec3(p, 1.0));\nfloat d = 0.0;\nfor(int i = 0; i < 64; i++) {\nfloat dist = map(ro + rd * d, t);\nif(dist < 0.001 || d > 10.0) break;\nd += dist;\n}\nif(d < 10.0) {\nvec3 pos = ro + rd * d;\nvec2 e = vec2(0.001, 0.0);\nvec3 n = normalize(vec3(\nmap(pos + e.xyy, t) - map(pos - e.xyy, t),\nmap(pos + e.yxy, t) - map(pos - e.yxy, t),\nmap(pos + e.yyx, t) - map(pos - e.yyx, t)\n));\nfloat diff = max(dot(n, normalize(vec3(1.0, 1.0, -1.0))), 0.0);\nvec3 col = manColor * (diff + 0.3);\nreturn mix(source, vec4(col, 1.0), intensity);\n}\nreturn mix(source, vec4(bgColor, 1.0), intensity);\n}",
