    code: "// NAME: Water Morph Creature\nuniform float intensity; // @min 0.0 @max 1.0 @default 0.8\nuniform float speed; // @min 0.0 @max 2.0 @default 0.8\nuniform float morphAmount; // @min 0.0 @max 5.0 @default 2.5\nuniform float liquidness; // @min 0.0 @max 1.0 @default 0.9\nuniform float tentaclesNum; // @min 1.0 @max 12.0 @default 5.0\nuniform vec3 colorA; // @default 0.1,0.9,0.5\nuniform vec3 colorB; // @default 0.9,0.2,0.6\nuniform vec3 colorC; // @default 0.8,0.7,0.1\nuniform vec3 waterColor; // @default 0.0,0.4,0.8\nmat2 rot(float a) {\nfloat c = cos(a), s = sin(a);\nreturn mat2(c, -s, s, c);\n}\nfloat smin(float a, float b, float k) {\nfloat h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\nreturn mix(b, a, h) - k * h * (1.0 - h);\n}\nfloat map(vec3 p, float t, float liq, float luma, float numTentacles) {\np.y += sin(t * 3.0) * 0.15;\np.xy *= rot(sin(t * 1.5) * 0.4);\nfloat body = length(p) - 0.2 - luma * 0.2 + sin(p.x * 12.0 + t * 2.0) * sin(p.y * 12.0 - t) * sin(p.z * 12.0) * 0.08 * liq;\nvec3 tp = p;\nfloat a = atan(tp.z, tp.x);\nfloat r = length(tp.xz);\nfloat sector = 6.2831853 / max(1.0, numTentacles);\na = mod(a + sector * 0.5, sector) - sector * 0.5;\ntp.x = r * cos(a) - 0.2;\ntp.z = r * sin(a);\ntp.x += sin(tp.y * 15.0 - t * 8.0) * 0.08 * liq;\ntp.z += cos(tp.y * 17.0 - t * 7.0) * 0.08 * liq;\nfloat tentacles = length(tp.xz) - 0.015 + tp.y * 0.01;\ntentacles = max(tentacles, tp.y - 0.1);\ntentacles = max(tentacles, -tp.y - 0.6);\nreturn smin(body, tentacles, 0.15);\n}\nvec3 calcNormal(vec3 p, float t, float liq, float luma, float numTentacles) {\nvec2 e = vec2(0.01, 0.0);\nreturn normalize(vec3(\nmap(p + e.xyy, t, liq, luma, numTentacles) - map(p - e.xyy, t, liq, luma, numTentacles),\nmap(p + e.yxy, t, liq, luma, numTentacles) - map(p - e.yxy, t, liq, luma, numTentacles),\nmap(p + e.yyx, t, liq, luma, numTentacles) - map(p - e.yyx, t, liq, luma, numTentacles)\n));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat luma = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nvec2 p = (uv - 0.5) * 2.0;\np.x *= resolution.x / (resolution.y + 0.0001);\nfloat t = time * speed + luma * morphAmount;\nvec3 ro = vec3(0.0, 0.0, -1.5 + luma * morphAmount * 0.3);\nvec3 rd = normalize(vec3(p, 1.0));\nfloat d = 0.0, dist = 0.0;\nvec3 pos;\nfloat glowAcc = 0.0;\nfor(int i = 0; i < 40; i++) {\npos = ro + rd * dist;\nd = map(pos, t, liquidness, luma, tentaclesNum);\nif(d < 0.002) break;\ndist += d * 0.8;\nglowAcc += 0.015 / (0.01 + d * d * 25.0);\nif(dist > 5.0) break;\n}\nvec3 aliveColor = mix(colorA, colorB, sin(t * 3.0 + pos.y * 8.0) * 0.5 + 0.5);\naliveColor = mix(aliveColor, colorC, cos(t * 2.0 + pos.x * 5.0) * 0.5 + 0.5);\nvec2 wuv = uv * 10.0;\nfloat w = sin(wuv.x + time) + cos(wuv.y + time * 0.8) + sin(wuv.x * 2.0 - time * 1.5) * 0.5;\nvec3 waterBg = mix(waterColor * 0.4, waterColor * 1.2, w * 0.25 + 0.5);\nvec3 finalColor = vec3(0.0);\nif (dist < 5.0) {\nvec3 n = calcNormal(pos, t, liquidness, luma, tentaclesNum);\nvec3 lightDir = normalize(vec3(sin(time * 2.0), 1.0, cos(time * 2.0)));\nfloat diff = max(dot(n, lightDir), 0.0);\nfloat spec = pow(max(dot(reflect(-lightDir, n), -rd), 0.0), 32.0);\nfloat fresnel = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);\nvec3 baseColor = mix(source.rgb, aliveColor, intensity);\nvec3 litColor = baseColor * (diff * 0.8 + 0.2) + spec * 0.5 + fresnel * aliveColor * 0.8;\nfinalColor = mix(waterBg, litColor, diff * 0.7 + 0.3);\n} else {\nfinalColor = waterBg;\n}\nfinalColor += aliveColor * glowAcc * 0.1 * intensity;\nvec4 result = vec4(mix(source.rgb, finalColor, intensity), source.a);\nfloat blackMask = smoothstep(0.0, 0.05, luma);\nreturn vec4(mix(source.rgb, result.rgb, blackMask), result.a);\n}",
