    code: "// NAME: LSD Entity with Wobble Edges (Black Suppressed)\nuniform float speed; // @min 0.1 @max 5.0 @default 1.0\nuniform float warpStrength; // @min 0.0 @max 1.0 @default 0.5\nuniform float colorIntensity; // @min 0.0 @max 3.0 @default 1.5\nuniform float complexity; // @min 1.0 @max 10.0 @default 4.0\nuniform float edgeStrength; // @min 0.0 @max 5.0 @default 2.0\nuniform float wobbleSpeed; // @min 0.0 @max 10.0 @default 3.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 bgTex = texture2D(tex, uv);\nfloat depth = dot(bgTex.rgb, vec3(0.299, 0.587, 0.114));\nfloat isNonBlack = step(0.02, length(bgTex.rgb));\nvec2 p = uv * complexity;\nfloat t = time * speed;\nfor(int i = 1; i <= 4; i++) {\nvec2 newP = p;\nfloat fi = float(i);\nnewP.x += (0.5 / fi) * sin(fi * p.y + t + 0.3) + depth * warpStrength * 0.5;\nnewP.y += (0.5 / fi) * cos(fi * p.x + t + 0.3) + depth * warpStrength * 0.5;\np = newP;\n}\nvec3 psychColor = 0.5 + 0.5 * cos(t * 2.0 + p.xyx * 1.5 + vec3(0.0, 2.0, 4.0));\nvec2 warpOffset = (p - uv * complexity) * 0.015 * warpStrength;\nfloat r = texture2D(tex, uv + warpOffset).r;\nfloat g = texture2D(tex, uv + warpOffset * 1.5).g;\nfloat b = texture2D(tex, uv + warpOffset * 2.0).b;\nvec3 warpedTex = vec3(r, g, b);\nvec3 finalColor = warpedTex * (1.0 + psychColor * colorIntensity * depth);\nfinalColor += psychColor * 0.2 * sin(t * 3.0 + depth * 10.0);\nvec2 wobbleOffset = vec2(sin(time * wobbleSpeed + uv.y * 15.0), cos(time * wobbleSpeed + uv.x * 15.0)) * 0.005;\nvec2 edgeUV = uv + wobbleOffset;\nvec2 texel = 1.0 / resolution;\nfloat c0 = length(texture2D(tex, edgeUV).rgb);\nfloat cx = length(texture2D(tex, edgeUV + vec2(texel.x, 0.0)).rgb);\nfloat cy = length(texture2D(tex, edgeUV + vec2(0.0, texel.y)).rgb);\nfloat edge = abs(c0 - cx) + abs(c0 - cy);\nfloat s1 = length(texture2D(tex, edgeUV + vec2(texel.x * 3.0, 0.0)).rgb);\nfloat s2 = length(texture2D(tex, edgeUV - vec2(texel.x * 3.0, 0.0)).rgb);\nfloat s3 = length(texture2D(tex, edgeUV + vec2(0.0, texel.y * 3.0)).rgb);\nfloat s4 = length(texture2D(tex, edgeUV - vec2(0.0, texel.y * 3.0)).rgb);\nfloat surroundLuma = s1 + s2 + s3 + s4;\nfloat edgeMask = smoothstep(0.1, 0.5, surroundLuma);\nfinalColor += psychColor * edge * edgeStrength * 5.0 * edgeMask;\nreturn mix(bgTex, vec4(finalColor, 1.0), isNonBlack);\n}",
