    code: "// NAME: Depth Blob Morpher\nuniform float morphSpeed; // @min 0.0 @max 5.0 @default 2.0\nuniform float tentacleDepth; // @min 0.0 @max 2.0 @default 0.8\nuniform float blobSize; // @min 0.5 @max 3.0 @default 1.0\nuniform float twistAmount; // @min 0.0 @max 5.0 @default 2.5\nuniform float tentacleCount; // @min 1.0 @max 12.0 @default 8.0\nuniform float colorSpeed; // @min 0.0 @max 10.0 @default 3.0\nuniform float circleSize; // @min 0.1 @max 2.0 @default 0.4\nuniform float morphStrength; // @min 0.0 @max 0.5 @default 0.15\nuniform float depthAmount; // @min 0.0 @max 2.0 @default 0.5\nfloat map(vec3 p, float time, sampler2D tex) {\nvec3 q = p;\nfloat twist = p.y * twistAmount + time * morphSpeed;\nfloat c = cos(twist);\nfloat s = sin(twist);\np.xz = mat2(c, -s, s, c) * p.xz;\nfloat d = length(p) - blobSize;\nfloat tentacles = sin(atan(p.x, p.z) * tentacleCount) * cos(p.y * 5.0 - time * morphSpeed * 3.0);\nvec2 projUV = clamp(q.xy * 0.3 + 0.5, 0.0, 1.0);\nfloat depth = dot(texture2D(tex, projUV).rgb, vec3(0.299, 0.587, 0.114));\nfloat baseShape = (d - tentacles * tentacleDepth - depth * depthAmount) * 0.5;\nfloat line = length(q.xz) - 0.08;\nfloat circle = length(q - vec3(0.0, -1.8, 0.0)) - circleSize;\nreturn min(baseShape, min(line, circle));\n}\nvec3 calcNormal(vec3 p, float time, sampler2D tex) {\nvec2 e = vec2(0.01, 0.0);\nreturn normalize(vec3(\nmap(p + e.xyy, time, tex) - map(p - e.xyy, time, tex),\nmap(p + e.yxy, time, tex) - map(p - e.yxy, time, tex),\nmap(p + e.yyx, time, tex) - map(p - e.yyx, time, tex)\n));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec2 p = (uv * 2.0 - 1.0);\np.x *= resolution.x / resolution.y;\nvec3 ro = vec3(0.0, 0.0, -3.5);\nvec3 rd = normalize(vec3(p, 1.0));\nfloat t = 0.0;\nfloat d = 0.0;\nfor(int i = 0; i < 64; i++) {\nvec3 pos = ro + rd * t;\nd = map(pos, time, tex);\nif(d < 0.001 || t > 10.0) break;\nt += d;\n}\nvec2 finalUV = uv;\nvec3 tint = vec3(1.0);\nvec3 addCol = vec3(0.0);\nif(t < 10.0) {\nvec3 pos = ro + rd * t;\nvec3 n = calcNormal(pos, time, tex);\nfinalUV = uv + n.xy * morphStrength;\nvec3 light = normalize(vec3(sin(time), 1.0, cos(time)));\nfloat diff = max(dot(n, light), 0.3);\nvec3 q = pos;\nfloat twist = q.y * twistAmount + time * morphSpeed;\nfloat c = cos(twist);\nfloat s = sin(twist);\nq.xz = mat2(c, -s, s, c) * q.xz;\ntint = 0.5 + 0.5 * sin(time * colorSpeed + q.y * 2.0 + vec3(0.0, 2.0, 4.0));\naddCol = tint * diff * 0.5;\n}\nvec4 source = texture2D(tex, finalUV);\nreturn vec4(source.rgb * tint + addCol, source.a);\n}",
