    code: "// NAME: Depth Morphed Mandala\nuniform float intensity; // @min 0.0 @max 5.0 @default 2.5\nuniform float speed; // @min 0.0 @max 3.0 @default 1.0\nuniform float complexity; // @min 1.0 @max 10.0 @default 4.0\nuniform float liftAmount; // @min 0.0 @max 1.0 @default 0.3\nuniform float centers; // @min 1.0 @max 10.0 @default 3.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nfloat t = time * speed;\nvec4 baseTex = texture2D(tex, uv);\nfloat depthMap = dot(baseTex.rgb, vec3(0.299, 0.587, 0.114));\nfloat liftMask = smoothstep(0.1, 0.9, depthMap);\nvec2 center = vec2(0.5);\nvec2 liftOffset = (uv - center) * liftMask * liftAmount;\nvec2 morphedUV = uv - liftOffset;\nvec2 p = fract(morphedUV * centers) * 2.0 - 1.0;\nfloat a = atan(p.y, p.x);\nfloat r = length(p);\nfloat segments = 8.0;\na = mod(a, 6.2831853 / segments);\na = abs(a - 3.1415926 / segments);\na += t * 0.2;\np = r * vec2(cos(a), sin(a));\nvec2 warp = vec2(\nnode_noise(p * complexity + t),\nnode_noise(p.yx * complexity - t)\n);\nvec2 finalUV = fract(morphedUV + warp * intensity * 0.05);\nvec4 mandalaColor = texture2D(tex, finalUV);\nvec3 phase = vec3(0.0, 2.094, 4.188);\nvec3 tripColor = 0.5 + 0.5 * sin(t * 2.0 + node_noise(warp * 5.0) * 5.0 + phase);\nmandalaColor.rgb *= tripColor * 1.5;\nvec2 texel = 1.0 / resolution;\nfloat depthX = dot(texture2D(tex, uv + vec2(texel.x, 0.0)).rgb, vec3(0.299, 0.587, 0.114));\nfloat depthY = dot(texture2D(tex, uv + vec2(0.0, texel.y)).rgb, vec3(0.299, 0.587, 0.114));\nvec3 normal = normalize(vec3(depthX - depthMap, depthY - depthMap, 0.05));\nvec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));\nfloat diffuse = max(dot(normal, lightDir), 0.0);\nvec3 finalRGB = mix(baseTex.rgb, mandalaColor.rgb, liftMask);\nfinalRGB += diffuse * liftMask * 0.4;\nreturn vec4(finalRGB, baseTex.a);\n}",
