    code: "// NAME: Creature Eye Tentacles\nuniform vec3 baseColor; // @default 0.2,0.7,0.4\nuniform float growth; // @min 0.0 @max 5.0 @default 3.0\nuniform float speed; // @min 0.0 @max 5.0 @default 1.5\nuniform vec3 irisColor; // @default 0.8,0.6,0.1\nuniform float pupilSize; // @min 0.05 @max 0.5 @default 0.22\nuniform float irisSize; // @min 0.1 @max 0.8 @default 0.50\nuniform float whiteSize; // @min 0.1 @max 1.0 @default 0.35\nuniform bool lookAround; // @default true\nuniform float lookAroundSpeed; // @min 0.1 @max 5.0 @default 0.74\nuniform float eyeSize; // @min 0.1 @max 1.0 @default 0.35\nuniform float eyeDepth; // @min 0.0 @max 2.0 @default 0.85\nmat2 rot(float a) {\nfloat s = sin(a), c = cos(a);\nreturn mat2(c, -s, s, c);\n}\nfloat smin(float a, float b, float k) {\nfloat h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\nreturn mix(b, a, h) - k * h * (1.0 - h);\n}\nfloat map(vec3 p, float time) {\nfloat breathe = sin(time * speed * 2.0) * 0.06;\nfloat d = length(p) - (1.0 + breathe);\nfloat ovalDist = length(vec2(p.x, p.y * 1.1)) - (eyeSize + 0.05);\nfloat rim = length(vec2(ovalDist, p.z - (eyeDepth - 0.1))) - 0.12;\nd = smin(d, rim, 0.35);\nfloat eyeSphere = length(p - vec3(0.0, 0.0, eyeDepth)) - eyeSize;\nd = smin(d, eyeSphere, 0.08);\nfloat tLen = growth + sin(time * speed) * 0.5;\nfor(int i = 0; i < 8; i++) {\nvec3 q = p;\nfloat fi = float(i);\nq.xy *= rot(fi * 0.7854);\nq.xz *= rot(fi * 1.3);\nfloat wriggle = sin(time * speed * 3.0 + q.y * 5.0) * 0.15;\nq.x += sin(q.y * 3.5 - time * speed * 2.5 + wriggle) * 0.25;\nq.z += cos(q.y * 2.8 - time * speed * 2.0 - wriggle) * 0.25;\nfloat t = length(q.xz) - 0.15 * clamp(1.0 - q.y / tLen, 0.0, 1.0);\nt = max(max(t, q.y - tLen), -q.y);\nd = smin(d, t, 0.4);\n}\nreturn d;\n}\nvec3 calcNormal(vec3 p, float time) {\nvec2 e = vec2(0.01, 0.0);\nreturn normalize(vec3(\nmap(p + e.xyy, time) - map(p - e.xyy, time),\nmap(p + e.yxy, time) - map(p - e.yxy, time),\nmap(p + e.yyx, time) - map(p - e.yyx, time)\n));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nvec2 p = (uv * 2.0 - 1.0);\np.x *= resolution.x / resolution.y;\nvec3 ro = vec3(0.0, 0.0, 5.0);\nvec3 rd = normalize(vec3(p, -1.5));\nfloat t = 0.0;\nfor(int i = 0; i < 64; i++) {\nvec3 pos = ro + rd * t;\nfloat d = map(pos, time);\nif(d < 0.01 || t > 10.0) break;\nt += d;\n}\nvec3 col = source.rgb;\nif(t < 10.0) {\nvec3 pos = ro + rd * t;\nvec3 n = calcNormal(pos, time);\nvec3 light = normalize(vec3(1.0, 1.0, 1.0));\nfloat diff = max(dot(n, light), 0.0);\nfloat amb = 0.2;\nfloat nVal = node_noise(pos.xy * 4.0 + time * 0.5);\nvec3 lightVar = baseColor * 1.2;\nvec3 darkVar = baseColor * 0.6;\nvec3 bodyColor = mix(darkVar, lightVar, nVal);\nvec3 blobColor = bodyColor * (diff + amb);\nvec3 dotPos = pos * 12.0 - normalize(pos) * length(pos) * 8.0;\nfloat dots = length(fract(dotPos) - 0.5);\nfloat dotMask = smoothstep(0.25, 0.15, dots);\nvec3 dotColor = baseColor * 0.3;\nblobColor = mix(blobColor, dotColor * (diff + amb), dotMask);\nfloat eyeDist = length(pos - vec3(0.0, 0.0, eyeDepth));\nfloat eyeMask = smoothstep(whiteSize + 0.06, whiteSize - 0.01, eyeDist);\nif (eyeMask > 0.0 && pos.z > eyeDepth - eyeSize * 0.8) {\nvec3 eyeN = normalize(pos - vec3(0.0, 0.0, eyeDepth));\nfloat animX = lookAround ? sin(time * lookAroundSpeed) * 0.3 : 0.0;\nfloat animY = lookAround ? cos(time * lookAroundSpeed * 0.8) * 0.3 : 0.0;\nvec2 eyeUv = eyeN.xy - vec2(animX, animY);\nfloat r = length(eyeUv);\nfloat a = atan(eyeUv.y, eyeUv.x);\nfloat n1 = node_noise(vec2(a * 8.0, r * 15.0));\nfloat veins = smoothstep(0.55, 0.7, node_noise(eyeUv * 20.0 + n1 * 4.0));\nfloat equatorMask = smoothstep(0.65, 0.95, r);\nvec3 scleraColor = mix(vec3(1.0), bodyColor, equatorMask * veins + equatorMask * 0.8);\nfloat noiseVal = node_noise(vec2(a * 5.0, r * 10.0));\nfloat striation = sin(a * 30.0 + noiseVal * 5.0) * 0.5 + 0.5;\nvec3 irisTex = mix(irisColor * 0.3, irisColor * 0.9, striation * noiseVal) * smoothstep(irisSize, irisSize - 0.1, r);\nvec3 eyeColor = mix(scleraColor, irisTex, 1.0 - smoothstep(irisSize - 0.02, irisSize, r));\nfloat dynamicPupil = pupilSize + sin(time * 2.0) * 0.02;\neyeColor = mix(eyeColor, vec3(0.0), 1.0 - smoothstep(dynamicPupil - 0.02, dynamicPupil, r));\nvec3 eyeLight = normalize(vec3(0.5, 0.5, 1.0));\nfloat spec = pow(max(dot(n, normalize(eyeLight + vec3(0.0, 0.0, 1.0))), 0.0), 32.0);\nvec3 finalEye = eyeColor * (diff + amb) + vec3(spec) * 0.8;\nblobColor = mix(blobColor, finalEye, eyeMask);\n}\ncol = blobColor;\n}\nreturn vec4(col, source.a);\n}",
