    code: "// NAME: Depth Morph Psytrance Tentacles\nuniform float speed; // @min 0.0 @max 5.0 @default 1.5\nuniform float amplitude; // @min 0.0 @max 1.5 @default 0.4\nuniform float frequency; // @min 0.1 @max 4.0 @default 1.0\nuniform float tunnelRadius; // @min 0.5 @max 3.0 @default 1.5\nuniform float twist; // @min 0.0 @max 0.5 @default 0.2\nuniform float tentacleCount; // @min 3.0 @max 16.0 @default 8.0\nuniform float morphStrength; // @min 0.0 @max 2.0 @default 1.2\nuniform float colorFreq; // @min 0.1 @max 5.0 @default 2.0\nmat2 rot(float a) {\nfloat s = sin(a), c = cos(a);\nreturn mat2(c, -s, s, c);\n}\nvec3 getRainbow(float t) {\nreturn 0.5 + 0.5 * cos(6.28318 * (vec3(1.0, 1.0, 1.0) * t + vec3(0.0, 0.33, 0.67)));\n}\nvec2 map(vec3 p, float t, float depth) {\np.xy *= rot(p.z * twist + t * 0.2);\nfloat angle = 6.283185 / tentacleCount;\nfloat a = atan(p.y, p.x);\nfloat r = length(p.xy);\nfloat id = floor((a + angle * 0.5) / angle);\nfloat local_a = mod(a + angle * 0.5, angle) - angle * 0.5;\nfloat dynamicRadius = tunnelRadius * (1.0 + (1.0 - depth) * morphStrength);\nvec3 q = vec3(r * cos(local_a) - dynamicRadius, r * sin(local_a), p.z);\nq.x += sin(q.z * frequency + t * 2.0 + id * 1.5) * amplitude;\nq.y += cos(q.z * (frequency * 0.75) + t * 1.2 + id) * amplitude;\nfloat body = length(q.xy) - 0.35;\nvec3 sp = vec3(q.x + 0.31, q.y, mod(q.z + 0.2, 0.4) - 0.2);\nfloat sucker = max(length(sp) - 0.12, -(length(vec3(sp.x + 0.05, sp.yz)) - 0.08));\nfloat d = min(body, sucker);\nreturn vec2(d * 0.6, (sucker < body) ? 1.0 : 0.0);\n}\nvec3 calcNormal(vec3 p, float t, float depth) {\nvec2 e = vec2(0.005, 0.0);\nreturn normalize(vec3(\nmap(p + e.xyy, t, depth).x - map(p - e.xyy, t, depth).x,\nmap(p + e.yxy, t, depth).x - map(p - e.yxy, t, depth).x,\nmap(p + e.yyx, t, depth).x - map(p - e.yyx, t, depth).x\n));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat depth = (source.r + source.g + source.b) / 3.0;\nif (depth < 0.01) {\nreturn vec4(0.0, 0.0, 0.0, 1.0);\n}\nvec2 p = (uv * 2.0 - 1.0) * vec2(resolution.x / resolution.y, 1.0);\nfloat t_move = time * speed;\nvec3 ro = vec3(0.0, 0.0, t_move * 2.5);\nvec3 rd = normalize(vec3(p, 1.5));\nrd.xy *= rot(t_move * 0.1);\nfloat t = 0.05;\nfloat mat = 0.0;\nfor(int i = 0; i < 50; i++) {\nvec2 res = map(ro + rd * t, t_move, depth);\nif(res.x < 0.001 || t > 20.0) break;\nt += res.x;\nmat = res.y;\n}\nvec3 col = vec3(0.0);\nif(t < 20.0) {\nvec3 pos = ro + rd * t;\nvec3 n = calcNormal(pos, t_move, depth);\nfloat diff = max(dot(n, normalize(ro + vec3(0.0, 0.0, 1.0) - pos)), 0.0);\nfloat rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);\nfloat colorShift = pos.z * colorFreq * 0.1 - t_move * 0.5;\nvec3 rainbowBody = getRainbow(colorShift);\nvec3 rainbowSucker = getRainbow(colorShift + 0.5);\ncol = mix(rainbowBody, rainbowSucker, mat) * (diff + 0.3) + (rim * 0.5);\ncol *= smoothstep(20.0, 5.0, t);\n}\nreturn vec4(col, 1.0);\n}",
