    code: "// NAME: Julia 3D Lit Plane\nuniform float speed; // @min 0.1 @max 2.0 @default 0.5\nuniform float morph; // @min 0.0 @max 5.0 @default 1.5\nuniform float zoom; // @min 0.5 @max 5.0 @default 1.5\nuniform vec3 color_shift; // @default 1.0,0.4,0.15\nuniform float tilt; // @min -1.0 @max 1.0 @default 0.5\nuniform float bump_strength; // @min 0.1 @max 5.0 @default 2.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nfloat t = time * speed;\nvec2 tilted_uv = uv - 0.5;\nfloat cosA = cos(tilt);\nfloat sinA = sin(tilt);\nfloat denom = 1.0 + tilted_uv.y * sinA;\ntilted_uv.x = tilted_uv.x / denom;\ntilted_uv.y = (tilted_uv.y * cosA) / denom;\ntilted_uv += 0.5;\ntilted_uv = clamp(tilted_uv, 0.0, 1.0);\nvec4 src = texture2D(tex, uv);\nvec2 p = (tilted_uv - 0.5) * 2.0 * zoom;\nvec2 c = vec2(-0.7, 0.27015) + vec2(sin(t), cos(t)) * 0.1 * morph;\nvec2 z = p;\nfloat h = 0.0;\nfor (int i = 0; i < 32; i++) {\nif (dot(z, z) < 4.0) {\nz = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;\nh += 1.0 / 32.0;\n}\n}\nvec3 normal = normalize(vec3(-z.x * bump_strength * 0.1, -z.y * bump_strength * 0.1, 1.0));\nvec3 light_dir = normalize(vec3(sin(t), cos(t), 1.0));\nfloat diffuse = max(dot(normal, light_dir), 0.0);\nvec3 fractal_color = sin(color_shift * h * 6.28) * 0.5 + 0.5;\nvec3 final_color = src.rgb * (fractal_color * (diffuse + 0.5));\nreturn vec4(final_color, src.a);\n}",
