    code: "// NAME: Interference Depth\nuniform float speed; // @min 0.1 @max 2.0 @default 0.5\nuniform float intensity; // @min 0.0 @max 1.0 @default 0.7\nuniform float depthInfluence; // @min 0.0 @max 3.0 @default 1.5\nmat2 rot(float a) {\nfloat c = cos(a);\nfloat s = sin(a);\nreturn mat2(c, -s, s, c);\n}\nvec2 M(vec2 p) {\np = abs(p) - 0.5;\np = p * rot(0.785398);\np = abs(p) - 0.2;\nreturn p;\n}\nvec2 Q(vec2 p) {\nfloat angle = floor(atan(p.x, p.y) * 4.0 + 0.5) / 4.0;\nreturn p * rot(angle);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 original = texture2D(tex, uv);\nfloat depth = max(original.r, max(original.g, original.b));\nvec2 aspect = vec2(resolution.x / resolution.y, 1.0);\nvec2 st = (uv - 0.5) * aspect * 2.0;\nfloat t = -time * speed * 2.0;\nvec4 O = vec4(0.0);\nfloat r = 0.0;\nfor (int i = 0; i < 20; i++) {\nfloat a = float(i);\nvec3 p = r * normalize(vec3(st, 1.0));\np.z -= 12.0 - depth * depthInfluence * 4.0;\np.xz = p.xz * rot(1.0 + cos(time * speed));\np.yz = p.yz * rot(1.0 + sin(time * speed));\np.xz = M(p.xz);\np.xy = Q(p.xy);\np.yz = M(p.yz);\np.xy = M(p.xy);\nfloat len = length(p.xy);\nif (len > 0.001) {\nO += (0.002 + 0.02 * smoothstep(0.9, 1.0, cos(length(p.xy + p.z) * 2.0 - t))) *\n(1.0 + cos(len * 2.0 + a * 0.2 + vec4(0.0, 1.0, 2.0, 0.0))) / len;\n}\np.yx = p.yx * rot(atan(p.y, p.x));\np.zx = p.zx * rot(atan(max(p.z, 0.0), p.x));\nvec3 f = vec3(0.0);\nf.x = pow(0.67, floor(t - log(max(p.x, 0.001)) / 0.4) - t);\nr += min(len, min(abs(length(p - f) - f.x * 0.2), abs(length(p - f * 0.67) - f.x * 0.134))) + 0.01;\n}\nvec3 interference = (exp(2.0 * O.rgb) - 1.0) / (exp(2.0 * O.rgb) + 1.0);\nvec3 finalColor = mix(original.rgb, interference, intensity * depth);\nfloat isNotBlack = step(0.01, depth);\nfinalColor *= isNotBlack;\nreturn vec4(finalColor, original.a * isNotBlack);\n}",
