    code: "// NAME: Masked Fractal Raymarcher\nuniform float speed; // @min 0.0 @max 2.0 @default 0.5\nuniform float glow_intensity; // @min 0.1 @max 3.0 @default 1.0\nuniform float aberration; // @min 0.0 @max 0.1 @default 0.025\nuniform float mix_bg; // @min 0.0 @max 1.0 @default 0.0\n#define MAX_STEPS 80\n#define MAX_DIST 30.0\n#define SURF_DIST 0.0015\nmat2 rot(float a) {\nfloat s = sin(a), c = cos(a);\nreturn mat2(c, -s, s, c);\n}\nvec3 pal(in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d) {\nreturn a + b * cos(6.28318 * (c * t + d));\n}\nfloat map(vec3 p, vec3 ro, float t) {\np.z = mod(p.z + 6.0, 12.0) - 6.0;\nvec3 p_orig = p;\nfloat scale = 1.0;\nvec3 offset = vec3(5.2, 0.9, 1.6);\nfor (int i = 0; i < 6; i++) {\np = abs(p) - offset;\np.xy *= rot(0.4);\np.yz *= rot(0.25);\np *= 1.5;\nscale *= 1.5;\n}\nfloat d = (abs(p.x) + abs(p.y) + abs(p.z) - 1.8) / scale;\nfloat geoWave = sin(length(p_orig) * 3.0 - t * 5.0) * 0.04;\nd += geoWave;\nfloat cameraLocalZ = mod(ro.z + 6.0, 12.0) - 6.0;\nvec3 localRo = vec3(ro.xy, cameraLocalZ);\nfloat cameraSafetySphere = 0.5 - length(p_orig - localRo);\nd = max(d, cameraSafetySphere);\nreturn d;\n}\nvec3 render(vec2 uv, float t, float glow_mult) {\nvec3 ro = vec3(sin(t * 0.3) * 0.5, cos(t * 0.4) * 0.5, t * 4.0);\nvec3 target = vec3(0.0, 0.0, ro.z + 5.0);\nvec3 f = normalize(target - ro);\nvec3 r = normalize(cross(vec3(0.0, 1.0, 0.0), f));\nvec3 u = cross(f, r);\nvec3 rd = normalize(f * 1.2 + uv.x * r + uv.y * u);\nfloat d0 = 0.0;\nfloat glow = 0.0;\nfor (int i = 0; i < MAX_STEPS; i++) {\nvec3 p = ro + rd * d0;\nfloat ds = map(p, ro, t);\nfloat lightWave = max(0.0, sin(p.z * 1.5 - t * 6.0));\nlightWave = pow(lightWave, 4.0);\nglow += (0.012 / (0.01 + ds * ds)) * (1.0 + lightWave * 12.0);\nd0 += ds * 0.5;\nif (d0 > MAX_DIST || abs(ds) < SURF_DIST) break;\n}\nvec3 baseColor = pal(d0 * 0.08 - t * 0.1,\nvec3(0.5, 0.5, 0.5),\nvec3(0.5, 0.5, 0.5),\nvec3(1.0, 1.0, 1.0),\nvec3(0.0, 0.33, 0.67));\nvec3 col = baseColor * glow * 0.02 * glow_mult;\nif (d0 < MAX_DIST) {\nfloat mixFactor = 1.0 - smoothstep(0.0, SURF_DIST * 2.0, map(ro + rd * d0, ro, t));\ncol = mix(col, baseColor * 0.5, mixFactor * 0.1);\n}\ncol = mix(col, vec3(0.0), smoothstep(MAX_DIST * 0.6, MAX_DIST, d0));\nreturn col;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat mask = smoothstep(0.01, 0.05, max(source.r, max(source.g, source.b)));\nvec2 aspect_uv = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0);\nfloat t = time * speed;\nfloat ca = length(aspect_uv) * aberration;\nfloat red = render(aspect_uv + aspect_uv * ca, t, glow_intensity).r;\nfloat green = render(aspect_uv, t, glow_intensity).g;\nfloat blue = render(aspect_uv - aspect_uv * ca, t, glow_intensity).b;\nvec3 col = vec3(red, green, blue);\ncol = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);\ncol = pow(col, vec3(1.0 / 2.2));\ncol *= 1.0 - length(aspect_uv) * 0.3;\nvec3 final_col = mix(source.rgb, mix(col, source.rgb, mix_bg), mask);\nreturn vec4(final_col, source.a);\n}",
