    description: "Imported from shadertoexport for Sculpture and Stage use.",
    code: "// NAME: Masked Depth Morphed Lit Ripple Fractal\nuniform float strength; // @min 0.0 @max 1.0 @default 0.8\nuniform float depth_scale; // @min -2.0 @max 2.0 @default 0.8\nuniform float speed; // @min 0.1 @max 3.0 @default 1.2\nuniform vec3 light_color; // @default 1.0,0.9,0.75\nuniform float ripple_amplitude; // @min 0.0 @max 0.1 @default 0.03\nuniform float ripple_frequency; // @min 1.0 @max 50.0 @default 20.0\nuniform float ripple_speed; // @min 0.0 @max 10.0 @default 4.0\nfloat getFractalHeight(vec2 st, float t) {\nvec2 z = st * 2.2;\nfloat iter = 0.0;\nfor (int i = 0; i < 6; i++) {\nfloat d = dot(z, z);\nif (d < 0.001) d = 0.001;\nif (length(z) < 12.0) {\nvec2 fold = vec2(0.8 + sin(t * 0.4) * 0.15, 0.6 + cos(t * 0.3) * 0.15);\nz = abs(z) / d - fold;\niter += 1.0;\n}\n}\nreturn iter * 0.2 + length(z) * 0.05;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nfloat t = time * speed;\nvec2 aspect = vec2(resolution.x / resolution.y, 1.0);\nvec2 toCenter = (uv - 0.5) * aspect;\nfloat dist = length(toCenter);\nvec2 dir = dist > 0.0001 ? toCenter / dist : vec2(0.0);\nfloat wave = sin(dist * ripple_frequency - time * ripple_speed) * ripple_amplitude;\nvec2 distortedUV = uv + (dir / aspect) * wave;\nvec4 source = texture2D(tex, distortedUV);\nfloat brightness = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nfloat mask = smoothstep(0.01, 0.05, brightness);\nfloat pulse = 1.0 + sin(t * 1.5) * 0.15;\nvec2 st = (distortedUV - 0.5) * aspect * pulse;\nfloat morph = brightness * depth_scale * 2.5;\nst += vec2(sin(t * 0.8 + morph), cos(t * 0.6 + morph)) * 0.25;\nfloat angle = t * 0.15 + brightness * 0.5;\nfloat ca = cos(angle);\nfloat sa = sin(angle);\nst = vec2(st.x * ca - st.y * sa, st.x * sa + st.y * ca);\nfloat h = getFractalHeight(st, t);\nvec2 eps = vec2(0.015, 0.0);\nfloat hx = getFractalHeight(st + eps.xy, t);\nfloat hy = getFractalHeight(st + eps.yx, t);\nvec3 normal = normalize(vec3((h - hx) / eps.x, (h - hy) / eps.x, 1.5));\nvec2 z = st * 2.2;\nfloat iter = 0.0;\nfor (int i = 0; i < 8; i++) {\nfloat d = dot(z, z);\nif (d < 0.001) d = 0.001;\nif (length(z) < 12.0) {\nvec2 fold = vec2(0.8 + sin(t * 0.4) * 0.15, 0.6 + cos(t * 0.3) * 0.15);\nz = abs(z) / d - fold;\niter += 1.0;\n}\n}\nvec3 fractalColor = 0.5 + 0.5 * cos(vec3(0.0, 1.5, 3.0) + iter * 0.5 + t * 1.5);\nfloat glow = 0.08 / (0.08 + abs(z.x)) + 0.08 / (0.08 + abs(z.y));\nfractalColor += vec3(glow * 0.4, glow * 0.6, glow * 0.8);\nfractalColor *= (1.0 / (1.0 + length(z) * 0.08));\nvec3 lightDir = normalize(vec3(0.5, 0.5, 1.0));\nfloat diff = max(dot(normal, lightDir), 0.0);\nvec3 litColor = fractalColor * (diff * light_color + 0.2);\nvec3 finalColor = mix(source.rgb, litColor, strength * mask);\nreturn vec4(finalColor, source.a);\n}",
