    code: "// NAME: Psytrance Morphed Hallway\nuniform float speed; // @min 0.1 @max 5.0 @default 1.5\nuniform float morphStrength; // @min 0.0 @max 5.0 @default 2.5\nuniform float zoom; // @min 0.5 @max 3.0 @default 1.2\nuniform float complexity; // @min 1.0 @max 8.0 @default 5.0\nuniform float colorFreq; // @min 1.0 @max 10.0 @default 4.0\nmat2 rot2d(float a) {\nfloat s = sin(a), c = cos(a);\nreturn mat2(c, -s, s, c);\n}\nfloat map(vec3 p, float time, float depthVal) {\np.xy *= rot2d(p.z * 0.5 + time * 1.2);\np.xyz += sin(p.zxy * 2.5 + time * 3.0) * (depthVal * morphStrength * 0.3);\nvec2 q = mod(p.xy, 2.0) - 1.0;\nfloat thickness = 0.15 + 0.08 * sin(p.z * 5.0 + time * 8.0);\nfloat tube = length(q) - thickness;\nreturn tube;\n}\nvec3 getPsyPalette(float t) {\nvec3 a = vec3(0.5, 0.5, 0.5);\nvec3 b = vec3(0.5, 0.5, 0.5);\nvec3 c = vec3(1.0, 1.0, 1.0);\nvec3 d = vec3(0.0, 0.33, 0.67);\nreturn a + b * cos(6.28318 * (c * t + d));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 texCol = texture2D(tex, uv);\nfloat depthVal = dot(texCol.rgb, vec3(0.299, 0.587, 0.114));\nvec2 q = (uv - 0.5) * 2.0;\nq.x *= resolution.x / resolution.y;\nfloat t = time * speed;\nvec3 ro = vec3(0.0, 0.0, t * 3.0);\nvec3 rd = normalize(vec3(q, zoom));\nrd.xy *= rot2d(depthVal * morphStrength * 0.3 + t * 0.2);\nfloat dO = 0.0;\nfloat dS = 0.0;\nfloat glow = 0.0;\nfor(int i = 0; i < 40; i++) {\nif (float(i) > complexity * 8.0) break;\nvec3 p = ro + rd * dO;\ndS = map(p, t, depthVal);\ndO += dS * 0.7;\nglow += exp(-abs(dS) * 6.0);\nif (dO > 25.0 || abs(dS) < 0.005) break;\n}\nvec3 p = ro + rd * dO;\nfloat fog = 1.0 / (1.0 + dO * dO * 0.05);\nfloat colorCoord = p.z * 0.1 * colorFreq - t * 0.8;\nvec3 baseCol = getPsyPalette(colorCoord);\nfloat strobe = 0.8 + 0.2 * sin(t * 12.0);\nvec3 glowCol = getPsyPalette(colorCoord + 0.5) * glow * 0.08 * strobe;\nvec3 col = baseCol * fog + glowCol;\nvec3 shiftedTex = getPsyPalette(depthVal + t * 0.5) * texCol.rgb * 1.5;\nvec3 finalCol = mix(shiftedTex, col, clamp(depthVal * 2.0, 0.0, 1.0));\nfinalCol = pow(finalCol, vec3(0.9)) * 1.2;\nreturn vec4(finalCol, texCol.a);\n}",
