    code: "// NAME: Depth Morph Fractal\nuniform float morph_strength; // @min 0.0 @max 2.0 @default 0.8\nuniform float speed; // @min 0.0 @max 2.0 @default 0.4\nuniform float scale; // @min 0.1 @max 5.0 @default 1.5\nuniform float displace; // @min 0.0 @max 0.5 @default 0.15\nuniform vec3 color_tint; // @default 0.5,0.8,1.0\nvec2 triangle_wave(vec2 a) {\nreturn abs(fract((a + vec2(1.0, 0.5)) * 1.5) - 0.5);\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat depth = (source.r + source.g + source.b) / 3.0;\nvec2 aspect = vec2(resolution.x / resolution.y, 1.0);\nvec2 f_uv = (uv - 0.5) * aspect * scale;\nfloat t = time * speed;\nf_uv += (depth - 0.5) * morph_strength;\nvec2 p = f_uv;\nfloat accum = 0.0;\nfloat amp = 1.0;\nvec2 shift = vec2(sin(t * 0.5), cos(t * 0.3)) * 0.2;\nfor(int i = 0; i < 6; i++) {\np = triangle_wave(p + shift) * 1.4 - 0.7;\nfloat angle = 0.785398 + float(i) * 0.5;\nfloat s = sin(angle);\nfloat c = cos(angle);\np = vec2(p.x * c - p.y * s, p.x * s + p.y * c);\naccum += length(p) * amp;\namp *= 0.7;\n}\nvec3 fractal_col = sin(vec3(accum * 1.5, accum * 2.0, accum * 2.5) + t) * 0.5 + 0.5;\nfractal_col *= color_tint;\nvec2 displacement = p * displace * (depth + 0.1);\nvec2 displaced_uv = uv + displacement;\ndisplaced_uv = clamp(displaced_uv, 0.0, 1.0);\nvec4 morphed_tex = texture2D(tex, displaced_uv);\nfloat blend_factor = depth * 0.6 + (1.0 - depth) * 0.1;\nvec3 final_rgb = mix(morphed_tex.rgb, fractal_col, blend_factor * clamp(accum * 0.3, 0.0, 1.0));\nreturn vec4(final_rgb, source.a);\n}",
