    code: "// NAME: Colorful Wave Tunnel\nuniform float speed; // @min 0.1 @max 5.0 @default 1.8\nuniform float blend; // @min 0.0 @max 1.0 @default 1.0\nuniform float depthMorph; // @min 0.0 @max 10.0 @default 4.0\nvec2 path(float z) {\nreturn vec2(sin(z * 0.2) * 1.5, cos(z * 0.15) * 1.2);\n}\nfloat map(vec3 p, float time) {\nvec3 q = p;\nq.xy -= path(q.z);\nfloat ang = atan(q.y, q.x);\nfloat ray = length(q.xy);\nfloat base = 2.5 - ray + 0.3 * sin(q.z * 1.5 - time * 1.5) * cos(ang * 6.0 + q.z);\nvec3 op = q;\nop.z = mod(op.z + time, 3.0) - 1.5;\nfloat nerv = length(vec2(ray - 2.6, op.z)) - 0.3 - 0.15 * sin(ang * 8.0 + p.z * 2.0);\nfloat k = 0.6;\nfloat h = clamp(0.5 + 0.5 * (nerv - base) / k, 0.0, 1.0);\nfloat d = mix(nerv, base, h) - k * h * (1.0 - h);\nreturn d * 0.5;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat depth = dot(source.rgb, vec3(0.3333));\nif (depth < 0.01) {\nreturn source;\n}\nvec2 p = (2.0 * uv - 1.0) * vec2(resolution.x / resolution.y, 1.0);\nfloat tc = time * speed + depth * depthMorph;\np *= 1.0 - depth * 0.2;\nvec3 ro = vec3(path(tc), tc);\nvec3 ta = vec3(path(tc + 1.5), tc + 1.5);\nvec3 cw = normalize(ta - ro);\nvec3 cp = vec3(sin(time * 0.4), cos(time * 0.4), 0.0);\nvec3 cu = normalize(cross(cw, cp));\nvec3 cv = cross(cu, cw);\nvec3 rd = mat3(cu, cv, cw) * normalize(vec3(p, 1.4));\nfloat t = 0.01;\nfloat glow = 0.0;\nfor (int i = 0; i < 60; i++) {\nfloat h = map(ro + rd * t, time);\nglow += 0.01 / (0.02 + abs(h));\nif (abs(h) < 0.002 * t || t > 30.0) {\nbreak;\n}\nt += h;\n}\nvec3 col = vec3(0.01, 0.01, 0.02);\nif (t < 30.0) {\nvec3 pos = ro + rd * t;\nvec3 waveColor = 0.5 + 0.5 * cos(pos.z * 1.5 - time * 4.0 + vec3(0.0, 2.0, 4.0));\nvec3 alb = waveColor * 0.5 + 0.1;\nfloat fog = 1.0 - exp(-0.02 * t * t);\ncol = mix(alb, vec3(0.02, 0.02, 0.04), fog);\n}\nvec3 glowColor = 0.5 + 0.5 * cos(time * 3.0 + vec3(0.0, 2.0, 4.0));\ncol += glowColor * glow * 0.02;\ncol = pow(clamp(col, 0.0, 1.0), vec3(0.4545));\nreturn mix(source, vec4(col, source.a), blend);\n}",
