    code: "// NAME: Green Morphed Worms\nconst int MAX_STEPS = 80;\nconst int NUM_SPHERES = 10;\nfloat sphere(vec3 pos, float radius, vec3 smpl) {\nreturn length(pos - smpl) - radius;\n}\nfloat plane(vec3 dir, float offset, vec3 smpl) {\nreturn dot(dir, smpl) + offset;\n}\nfloat dfDist(vec3 smpl, float time, sampler2D tex, vec3 opos) {\nfloat T1 = 10.0, T2 = 20.0, result = 10000.0;\nvec3 modSmpl = smpl;\nfloat var = sin(modSmpl.x * 0.5 + time) * cos(modSmpl.z * 0.4 - time);\nmodSmpl.y += sin(modSmpl.z * 0.2 + time) * sin(time * 1.33) + sin(modSmpl.x * 0.3 + time) * sin(time * 3.22) + var;\nfloat o = floor((modSmpl.z + T1) / T2);\nmodSmpl.x += o * 7.0;\nmodSmpl.xz = mod(modSmpl.xz + T1, T2) - T1;\nfor (int i = 0; i < NUM_SPHERES; i++) {\nfloat t = float(i) / float(NUM_SPHERES);\nfloat n = t + time * 0.25 + o * 0.5;\nvec3 pos = vec3(sin(n * 5.0) * 5.0, cos(n * 3.0) * 9.0, cos(n * 2.0) * 3.0 + 5.0);\nfloat radius = texture2D(tex, vec2(t, 0.5)).x * 2.0 + 1.0 + sin(n * 10.0) * 0.5;\nresult = min(result, sphere(pos, radius, modSmpl));\n}\nresult = min(result, plane(vec3(0.0, -1.0, 0.0), 12.0, modSmpl));\nresult = min(result, plane(vec3(0.0, 1.0, 0.0), 12.0, modSmpl));\nresult = max(result, 2.5 - length(smpl - opos));\nreturn result;\n}\nvec3 dfNormal(vec3 smpl, float time, sampler2D tex, vec3 opos) {\nvec2 e = vec2(0.04, 0.0);\nfloat d0 = dfDist(smpl, time, tex, opos);\nreturn normalize(vec3(\ndfDist(smpl + e.xyy, time, tex, opos) - d0,\ndfDist(smpl + e.yxy, time, tex, opos) - d0,\ndfDist(smpl + e.yyx, time, tex, opos) - d0\n));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat depth = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nif (depth < 0.01) {\nreturn source;\n}\nvec2 fragCoord = uv * resolution;\nvec3 opos = vec3(4.5 + depth * 3.0, sin(time * 0.4) * 3.0 + 2.0 - depth * 2.0, -7.0 + time * 3.0 + depth * 5.0);\nvec3 pos = opos;\nvec3 dir = normalize(vec3((fragCoord.x - resolution.x * 0.5) / resolution.y, fragCoord.y / resolution.y - 0.5, 1.0));\nfor (int i = 0; i < MAX_STEPS; i++) {\nfloat d = dfDist(pos, time, tex, opos);\npos += d * dir;\nif (d < 0.001) break;\n}\nvec3 normal = dfNormal(pos, time, tex, opos);\nfloat occ = clamp(dfDist(pos + normal, time, tex, opos), 0.0, 1.0);\nfloat fogAmt = 1.0 - exp(-distance(opos, pos) * 0.015);\nvec3 baseColor = vec3(\n0.1 + 0.15 * sin(pos.x * 2.0 + time),\n0.6 + 0.4 * cos(pos.z * 1.5 - time),\n0.2 + 0.2 * sin(pos.y * 2.0)\n);\nvec3 diffuse = baseColor * max(0.0, dot(normal, normalize(vec3(1.0, 0.8, -0.5))));\nvec3 ambient = baseColor * occ * 0.5;\nvec3 finalColor = mix(diffuse + ambient, vec3(0.0), fogAmt);\nreturn vec4(finalColor, source.a);\n}",
