    code: "// NAME: Hyper Psychedelic Morph\n#define pi2 3.141592653589793\nuniform float morphAmount; // @min 0.0 @max 2.0 @default 1.0\nuniform float psychSpeed; // @min 0.0 @max 5.0 @default 2.0\nuniform float complexity; // @min 1.0 @max 5.0 @default 3.0\nfloat tri(float x, float s) { return (abs(fract(x / s) - 0.5) - 0.25) * s; }\nfloat hash(float x) { return fract(sin(x * 171.2972) * 18267.978 + 31.287); }\nvec2 hash2(vec2 p) { return fract(1965.5786 * vec2(sin(p.x * 591.32 + p.y * 154.077), cos(p.x * 391.32 + p.y * 49.077))); }\nvec3 pix(vec2 p, float t, float s) {\ns += floor(t * 0.25);\nfloat scl = (hash(s + 30.0) * 4.0) + sin(t * 2.0) * 0.25 + sin(t) * 0.5 + complexity * 0.5;\nt *= 3.0;\nvec2 pol = vec2(atan(p.y, p.x), length(p));\nfloat id = floor(pol.y * 2.0 * scl);\npol.x += t * (hash(id + s) * 2.0 - 1.0) * 0.4;\nfloat si = hash(id + s * 2.0);\nfloat rp = floor(hash(id + s * 4.0) * 5.0 + 4.0);\nfloat v = (abs(tri(pol.x, pi2 / rp)) - si * 0.1) * pol.y;\nv = max(v, abs(tri(pol.y, 1.0 / scl)) - (1.0 - si) * 0.11);\nreturn vec3(smoothstep(0.01, 0.0, v));\n}\nvec3 pix2(vec2 p, float t, float s) {\nreturn clamp(pix(p, t, s) - pix(p, t, s + 8.0) + pix(p * 0.1, t, s + 80.0) * 0.2, 0.0, 1.0);\n}\nvec3 blur(vec2 p, float gt) {\nvec3 ite = vec3(0.0);\nfor(int i = 0; i < 10; i++) {\nite += pix2(p, gt * 3.0 + (hash2(p + float(i)) - 0.5).x * 0.15, 5.0);\n}\nreturn (ite / 10.0) + exp(fract(gt * 0.25 * 6.0) * -40.0) * 2.0;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 src = texture2D(tex, uv);\nfloat depth = dot(src.rgb, vec3(0.299, 0.587, 0.114));\nif (depth < 0.01) return src;\nfloat gt = time * psychSpeed * 0.5 - 2.555;\nvec2 p = 2.0 * uv - 1.0;\np.x *= resolution.x / resolution.y;\nvec2 warp = vec2(node_noise(p * complexity + time), node_noise(p * complexity - time));\np += warp * 0.15 * morphAmount;\np *= 1.0 - (depth * morphAmount * 0.5);\np += (uv - 0.5) * depth * morphAmount;\np += (vec2(hash(gt), hash(gt + 9.999)) - 0.5) * 0.03;\nvec3 c = vec3(\nblur(p + vec2(0.015, 0.0), gt).x,\nblur(p + vec2(0.0, 0.015), gt).y,\nblur(p - vec2(0.015, 0.015), gt).z\n);\nc = pow(c, vec3(0.8, 1.2, 2.0)) * 1.5;\nc *= exp(length(p) * -1.0) * 2.5;\nvec3 psych1 = 0.5 + 0.5 * cos(time * psychSpeed + length(p) * 8.0 + warp.xyx * 5.0 + vec3(0.0, 2.0, 4.0) + depth * 6.28);\nvec3 psych2 = 0.5 + 0.5 * sin(time * psychSpeed * 1.3 - p.xyx * 12.0 + vec3(1.0, 2.5, 5.0));\nc *= mix(psych1, psych2, 0.5);\nreturn vec4(mix(src.rgb, c, clamp(morphAmount, 0.0, 1.0)), src.a);\n}",
