    code: "// NAME: SuperNovae Depth Morph\nuniform float morphAmount; // @min 0.0 @max 5.0 @default 2.0\nvec2 cmul(vec2 a, vec2 b) {\nreturn vec2(a.x*b.x - a.y*b.y, a.x*b.y + a.y*b.x);\n}\nvec3 dmul(vec3 a, vec3 b) {\nfloat r = length(a);\nb.xy = cmul(normalize(a.xy), b.xy);\nb.yz = cmul(normalize(a.yz), b.yz);\nb.xz += 0.3 * cmul(normalize(a.xz), b.xz);\nreturn r*b;\n}\nfloat field(in vec3 p) {\nfloat res = 0.0;\nvec3 c = p;\nfor (int i = 0; i < 10; ++i) {\np = abs(p) / dot(p,p) - 1.0;\np = dmul(p,p) + 0.7;\nres += exp(-6.0 * abs(dot(p,c)-0.15));\n}\nreturn max(0.0, res / 3.0);\n}\nvec3 raycast(in vec3 ro, vec3 rd) {\nfloat t = 1.5;\nfloat dt = 0.25;\nvec3 col = vec3(0.0);\nfor(int i = 0; i < 5; i++) {\nfloat c = field(ro + t*rd);\nt += dt / (0.35 + c*c);\nc = max(5.0 * c - 0.9, 0.0);\nc = c*c*c*c;\ncol = 0.04*col + 0.04*vec3(0.1*c*c, 0.2*c, 0.0);\n}\nreturn col;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nif (length(source.rgb) < 0.01 || source.a < 0.01) {\nreturn source;\n}\nfloat depth = dot(source.rgb, vec3(0.3333));\nvec2 p = -1.0 + 2.0 * uv;\np.x *= resolution.x / resolution.y;\nfloat angle = 0.05 * time;\nvec3 ro = vec3(3.2 * cos(angle) + 0.5, 0.0, 3.2 * sin(angle) + 0.5);\nvec3 ta = vec3(0.0, 1.2, 0.0);\nvec3 ww = normalize(ta - ro);\nvec3 uu = normalize(cross(ww, vec3(0.0, 1.0, 0.0)));\nvec3 vv = normalize(cross(uu, ww));\nvec3 rd = normalize(p.x*uu + p.y*vv + 4.0*ww);\nro -= rd * depth * morphAmount * 2.0;\nvec3 col = raycast(ro, rd);\ncol = 0.3 * log(1.0 + 0.2 * col);\nvec3 finalColor = sqrt(col);\nreturn vec4(finalColor, source.a);\n}",
