    code: "// NAME: Depth Fractal Starfield\n#define NUM_LAYERS 10.0\nmat2 Rot(float a) {\nfloat c = cos(a), s = sin(a);\nreturn mat2(c, -s, s, c);\n}\nfloat Star(vec2 uv, float flare) {\nfloat d = length(uv);\nfloat m = 0.02 / d;\nfloat rays = max(0.0, 1.0 - abs(uv.x * uv.y * 1000.0));\nm += rays * flare;\nuv *= Rot(0.785398);\nrays = max(0.0, 1.0 - abs(uv.x * uv.y * 1000.0));\nm += rays * 0.3 * flare;\nm *= smoothstep(1.0, 0.2, d);\nreturn m;\n}\nfloat Hash21(vec2 p) {\np = fract(p * vec2(123.34, 456.21));\np += dot(p, p + 45.32);\nreturn fract(p.x * p.y);\n}\nvec3 StarLayer(vec2 uv, float time) {\nvec3 col = vec3(0.0);\nvec2 gv = fract(uv) - 0.5;\nvec2 id = floor(uv);\nfor(int y = -1; y <= 1; y++) {\nfor(int x = -1; x <= 1; x++) {\nvec2 offs = vec2(float(x), float(y));\nfloat n = Hash21(id + offs);\nfloat size = fract(n * 345.32);\nvec2 p = vec2(n, fract(n * 34.0));\nfloat star = Star(gv - offs - p + 0.5, smoothstep(0.8, 1.0, size) * 0.6);\nvec3 hueShift = fract(n * 2345.2 + dot(uv / 420.0, vec2(0.5))) * vec3(0.2, 0.3, 0.9) * 123.2;\nvec3 color = sin(hueShift) * 0.5 + 0.5;\ncolor = color * vec3(1.0, 0.25, 1.0 + size);\nstar *= sin(time * 3.0 + n * 6.2831) * 0.4 + 1.0;\ncol += star * size * color;\n}\n}\nreturn col;\n}\nvec2 N(float angle) {\nreturn vec2(sin(angle), cos(angle));\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nif (dot(source.rgb, vec3(1.0)) < 0.01) {\nreturn source;\n}\nfloat depthMap = source.r;\nvec2 p = (uv - 0.5) * resolution / resolution.y;\np *= 1.0 - depthMap * 0.3;\nfloat t = time * 0.01;\np.x = abs(p.x);\np.y += tan((5.0 / 6.0) * 3.1415) * 0.5;\nvec2 n = N((5.0 / 6.0) * 3.1415);\nfloat d = dot(p - vec2(0.5, 0.0), n);\np -= n * max(0.0, d) * 2.0;\nn = N((2.0 / 3.0) * 3.1415);\np.x += 1.5 / 1.25;\nfor(int i = 0; i < 5; i++) {\np *= 1.25;\np.x -= 1.5;\np.x = abs(p.x);\np.x -= 0.5;\np -= n * min(0.0, dot(p, n)) * 2.0;\n}\np *= Rot(t);\nvec3 col = vec3(0.0);\nfor(int i = 0; i < 10; i++) {\nfloat fi = float(i) / NUM_LAYERS;\nfloat depth = fract(fi + t - depthMap * 0.5);\nfloat s = mix(20.0, 0.5, depth);\nfloat fade = depth * smoothstep(1.0, 0.9, depth);\ncol += StarLayer(p * s + fi * 453.2, time) * fade;\n}\nreturn vec4(col, 1.0);\n}",
