    code: "// NAME: Ultra Smooth Psychedelic\nuniform float depthScale; // @min 0.0 @max 50.0 @default 15.0\nuniform vec3 lightPos; // @default 0.0,0.0,2.0\nuniform float shininess; // @min 1.0 @max 100.0 @default 32.0\nuniform bool animateLight; // @default true\nuniform float psychSpeed; // @min 0.0 @max 10.0 @default 2.0\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nvec3 luma = vec3(0.299, 0.587, 0.114);\nfloat d0 = dot(source.rgb, luma);\nif (d0 < 0.001) {\nreturn source;\n}\nvec2 step = 1.0 / resolution;\nfloat tl = dot(texture2D(tex, uv + vec2(-step.x, step.y)).rgb, luma);\nfloat t = dot(texture2D(tex, uv + vec2( 0.0, step.y)).rgb, luma);\nfloat tr = dot(texture2D(tex, uv + vec2( step.x, step.y)).rgb, luma);\nfloat l = dot(texture2D(tex, uv + vec2(-step.x, 0.0)).rgb, luma);\nfloat r = dot(texture2D(tex, uv + vec2( step.x, 0.0)).rgb, luma);\nfloat bl = dot(texture2D(tex, uv + vec2(-step.x, -step.y)).rgb, luma);\nfloat b = dot(texture2D(tex, uv + vec2( 0.0, -step.y)).rgb, luma);\nfloat br = dot(texture2D(tex, uv + vec2( step.x, -step.y)).rgb, luma);\nfloat dx = (tr + 2.0 * r + br) - (tl + 2.0 * l + bl);\nfloat dy = (tl + 2.0 * t + tr) - (bl + 2.0 * b + br);\nvec3 normal = normalize(vec3(-dx * depthScale, -dy * depthScale, 1.0));\nvec3 lp = lightPos;\nif (animateLight) {\nlp.x += sin(time) * 1.5;\nlp.y += cos(time) * 1.5;\n}\nvec3 pixelPos = vec3(uv * 2.0 - 1.0, d0);\nvec3 lightDir = normalize(lp - pixelPos);\nvec3 viewDir = vec3(0.0, 0.0, 1.0);\nfloat diff = max(dot(normal, lightDir), 0.0);\nvec3 halfDir = normalize(lightDir + viewDir);\nfloat spec = pow(max(dot(normal, halfDir), 0.0), shininess);\nfloat tm = time * psychSpeed;\nvec3 phase = vec3(0.0, 2.094, 4.188);\nvec3 psychBase = 0.5 + 0.5 * cos(tm * 1.5 + d0 * 4.0 + normal.x * 2.0 + phase);\nvec3 psychLight = 0.5 + 0.5 * sin(tm * 2.0 - d0 * 3.0 + normal.y * 2.0 + phase.zxy);\nvec3 psychSpec = 0.5 + 0.5 * cos(tm * 2.5 + normal.z * 3.0 + phase.yzx);\nvec3 ambient = psychBase * 0.3;\nvec3 diffuse = psychBase * psychLight * diff * 1.5;\nvec3 specular = psychSpec * spec * 0.9;\nvec3 finalColor = ambient + diffuse + specular;\nreturn vec4(finalColor, source.a);\n}",
