    code: "// NAME: Smooth 3D Surface\nuniform float depthScale; // @min 0.0 @max 50.0 @default 15.0\nuniform float heightScale; // @min 0.0 @max 1.0 @default 0.2\nuniform float shadowStrength; // @min 0.0 @max 1.0 @default 0.8\nuniform float smoothness; // @min 1.0 @max 10.0 @default 3.0\nuniform float lightSpeed; // @min 0.0 @max 5.0 @default 1.5\nuniform float lightRadius; // @min 0.0 @max 1.0 @default 0.4\nuniform float lightZ; // @min 0.1 @max 2.0 @default 0.5\nuniform float specIntensity; // @min 0.0 @max 5.0 @default 1.5\nuniform float shininess; // @min 1.0 @max 128.0 @default 64.0\nuniform float lightSize; // @min 0.0 @max 0.1 @default 0.015\nuniform float bgThreshold; // @min 0.0 @max 1.0 @default 0.05\nuniform vec3 baseColor; // @default 0.5,0.5,0.5\nuniform vec3 ambientColor; // @default 0.1,0.1,0.15\nuniform vec3 lightColor; // @default 1.0,0.9,0.7\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec2 eps = vec2(smoothness / resolution.x, smoothness / resolution.y);\nfloat d00 = texture2D(tex, uv + vec2(-eps.x, -eps.y)).r;\nfloat d10 = texture2D(tex, uv + vec2( 0.0, -eps.y)).r;\nfloat d20 = texture2D(tex, uv + vec2( eps.x, -eps.y)).r;\nfloat d01 = texture2D(tex, uv + vec2(-eps.x, 0.0)).r;\nfloat d11 = texture2D(tex, uv).r;\nfloat d21 = texture2D(tex, uv + vec2( eps.x, 0.0)).r;\nfloat d02 = texture2D(tex, uv + vec2(-eps.x, eps.y)).r;\nfloat d12 = texture2D(tex, uv + vec2( 0.0, eps.y)).r;\nfloat d22 = texture2D(tex, uv + vec2( eps.x, eps.y)).r;\nfloat centerDepth = (d00 + d10 + d20 + d01 + d11 + d21 + d02 + d12 + d22) / 9.0;\nfloat dx = ((d20 + 2.0 * d21 + d22) - (d00 + 2.0 * d01 + d02)) * 0.125;\nfloat dy = ((d02 + 2.0 * d12 + d22) - (d00 + 2.0 * d10 + d20)) * 0.125;\nvec3 normal = normalize(vec3(-dx * depthScale, -dy * depthScale, 1.0));\nfloat lx = sin(time * lightSpeed) * lightRadius;\nfloat ly = cos(time * lightSpeed) * lightRadius;\nvec3 lightPos = vec3(lx, ly, lightZ);\nvec3 pixelPos = vec3(uv.x - 0.5, uv.y - 0.5, centerDepth * heightScale);\nvec3 lightDir = normalize(lightPos - pixelPos);\nvec3 viewDir = vec3(0.0, 0.0, 1.0);\nfloat diff = max(dot(normal, lightDir), 0.0);\nvec3 halfVector = normalize(lightDir + viewDir);\nfloat spec = pow(max(dot(normal, halfVector), 0.0), shininess) * specIntensity;\nfloat shadow = 1.0;\nvec2 lightUV = vec2(0.5) + vec2(lx, ly);\nvec2 rayStep = (lightUV - uv) / 25.0;\nfloat zStep = (lightZ - pixelPos.z) / 25.0;\nvec2 sUv = uv;\nfloat sZ = pixelPos.z;\nfor(int i = 0; i < 25; i++) {\nsUv += rayStep;\nsZ += zStep;\nif(sUv.x < 0.0 || sUv.x > 1.0 || sUv.y < 0.0 || sUv.y > 1.0) break;\nfloat sDepth = texture2D(tex, sUv).r * heightScale;\nif(sDepth > sZ + 0.01) {\nshadow = 1.0 - shadowStrength;\nbreak;\n}\n}\nvec3 surfaceIllumination = ambientColor + (lightColor * diff * shadow) + (lightColor * spec * shadow);\nvec3 finalColor = baseColor * surfaceIllumination;\nfloat mask = smoothstep(bgThreshold - 0.02, bgThreshold + 0.02, centerDepth);\nfinalColor *= mask;\nfloat distToLight = length(uv - lightUV);\nfloat lightGlow = smoothstep(lightSize * 3.0, 0.0, distToLight) * 0.5;\nfloat lightCore = smoothstep(lightSize, lightSize * 0.8, distToLight);\nvec3 visibleLight = lightColor * (lightCore + lightGlow);\nfinalColor += visibleLight;\nreturn vec4(finalColor, 1.0);\n}",
