    code: "// NAME: Precise 3 Target Eyes with Saccade Blink\nuniform float greenThreshold; // @min -0.5 @max 0.5 @default 0.05\nuniform vec3 irisColor; // @default 0.415,0.627,0.827\nuniform float pupilSize; // @min 0.05 @max 0.5 @default 0.22\nuniform float irisSize; // @min 0.1 @max 0.8 @default 0.50\nuniform float lightIntensity; // @min 0.0 @max 3.0 @default 1.17\nuniform float eye1X; // @min 0.0 @max 1.0 @default 0.60\nuniform float eye1Y; // @min 0.0 @max 1.0 @default 0.50\nuniform float eye2X; // @min 0.0 @max 1.0 @default 0.40\nuniform float eye2Y; // @min 0.0 @max 1.0 @default 0.50\nuniform float eye3X; // @min 0.0 @max 1.0 @default 0.50\nuniform float eye3Y; // @min 0.0 @max 1.0 @default 0.65\nuniform bool lookAround; // @default true\nuniform float lookAroundSpeed; // @min 0.1 @max 5.0 @default 0.74\nuniform bool epilepsyMode; // @default false\nuniform bool independentEyes; // @default false\nuniform float targetX; // @min 0.0 @max 1.0 @default 0.50\nuniform float targetY; // @min 0.0 @max 1.0 @default 0.50\nuniform float targetZ; // @min 0.1 @max 5.0 @default 0.50\nuniform float eyeRadius; // @min 0.01 @max 0.5 @default 0.06\nuniform bool enableBlink; // @default true\nuniform vec3 blinkColor; // @default 0.15,0.1,0.1\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat greenness = source.g - max(source.r, source.b);\nfloat mask = smoothstep(greenThreshold, greenThreshold + 0.1, greenness);\nvec2 aspect = vec2(resolution.x / resolution.y, 1.0);\nvec2 uvAspect = uv * aspect;\nvec2 pos1 = vec2(eye1X, eye1Y) * aspect;\nvec2 pos2 = vec2(eye2X, eye2Y) * aspect;\nvec2 pos3 = vec2(eye3X, eye3Y) * aspect;\nfloat d1 = length(uvAspect - pos1);\nfloat d2 = length(uvAspect - pos2);\nfloat d3 = length(uvAspect - pos3);\nfloat d = min(min(d1, d2), d3);\nvec2 activePos = pos1;\nfloat eyeIndex = 1.0;\nif (d == d2) { activePos = pos2; eyeIndex = 2.0; }\nif (d == d3) { activePos = pos3; eyeIndex = 3.0; }\nvec2 eyeUV = (uvAspect - activePos) / eyeRadius;\nfloat r = length(eyeUV);\nfloat speed = epilepsyMode ? 30.0 : lookAroundSpeed;\nfloat t = time * speed;\nfloat f_t = floor(t);\nfloat fract_t = fract(t);\nfloat fr_t = epilepsyMode ? 0.0 : smoothstep(0.8, 1.0, fract_t);\nfloat seedOffset = independentEyes ? (eyeIndex == 3.0 ? 3.0 : 1.0) * 13.37 : 0.0;\nfloat randX1 = mix(0.2, 0.8, node_rand(vec2(f_t, 1.0 + seedOffset)));\nfloat randX2 = mix(0.2, 0.8, node_rand(vec2(f_t + 1.0, 1.0 + seedOffset)));\nfloat animX = mix(randX1, randX2, fr_t);\nfloat randY1 = mix(0.2, 0.8, node_rand(vec2(f_t, 2.0 + seedOffset)));\nfloat randY2 = mix(0.2, 0.8, node_rand(vec2(f_t + 1.0, 2.0 + seedOffset)));\nfloat animY = mix(randY1, randY2, fr_t);\nfloat finalTargetX = lookAround ? animX : targetX;\nfloat finalTargetY = lookAround ? animY : targetY;\nvec3 target3D = vec3(finalTargetX * aspect.x, finalTargetY, targetZ);\nvec3 eye3D = vec3(activePos, 0.0);\nvec3 lookDir = normalize(target3D - eye3D);\nvec2 lookOffset = lookDir.xy * 0.6;\nvec2 irisUV = eyeUV - lookOffset;\nfloat r_iris = length(irisUV);\nfloat a_iris = atan(irisUV.y, irisUV.x);\nfloat z = sqrt(max(1.0 - r * r, 0.0));\nvec3 N = normalize(vec3(eyeUV.x, eyeUV.y, z));\nvec3 L = normalize(vec3(0.5, 0.5, 1.0));\nfloat diff = (0.4 + 0.6 * max(dot(N, L), 0.0)) * lightIntensity;\nvec3 V = vec3(0.0, 0.0, 1.0);\nvec3 H = normalize(L + V);\nfloat spec = pow(max(dot(N, H), 0.0), 16.0) * lightIntensity * 0.15;\nvec3 scleraColor = mix(vec3(0.85, 0.82, 0.82), vec3(0.6, 0.2, 0.2), smoothstep(0.6, 1.0, r));\nfloat noiseVal = node_noise(vec2(a_iris * 5.0, r_iris * 10.0));\nfloat striation = sin(a_iris * 30.0 + noiseVal * 5.0) * 0.5 + 0.5;\nvec3 irisTex = mix(irisColor * 0.3, irisColor * 0.9, striation * noiseVal);\nirisTex *= smoothstep(irisSize, irisSize - 0.1, r_iris);\nvec3 eyeColor = mix(scleraColor, irisTex, 1.0 - smoothstep(irisSize - 0.02, irisSize, r_iris));\nfloat dynamicPupil = pupilSize + sin(time * 2.0) * 0.02;\neyeColor = mix(eyeColor, vec3(0.0), 1.0 - smoothstep(dynamicPupil - 0.02, dynamicPupil, r_iris));\neyeColor = eyeColor * diff + vec3(spec) * smoothstep(0.95, 0.85, r);\nvec3 finalEyeColor = eyeColor;\nfloat finalAlphaMask = (r > 1.0) ? 0.0 : 1.0 - smoothstep(0.85, 0.95, r);\nif (enableBlink) {\nfloat bAmount = epilepsyMode ? 0.0 : (smoothstep(0.75, 0.85, fract_t) - smoothstep(0.85, 1.0, fract_t));\nfloat topLid = mix(1.2, -0.1, bAmount);\nfloat bottomLid = mix(-1.2, 0.1, bAmount);\nfloat lidMask = smoothstep(topLid - 0.15, topLid + 0.05, eyeUV.y) + (1.0 - smoothstep(bottomLid - 0.05, bottomLid + 0.15, eyeUV.y));\nlidMask = clamp(lidMask, 0.0, 1.0);\nif (lidMask > 0.0) {\nfloat lidRadius = 1.05;\nfloat z_lid = sqrt(max(lidRadius * lidRadius - r * r, 0.0));\nvec3 N_lid = normalize(vec3(eyeUV.x, eyeUV.y, z_lid));\nfloat diff_lid = (0.4 + 0.6 * max(dot(N_lid, L), 0.0)) * lightIntensity;\nfloat spec_lid = pow(max(dot(N_lid, H), 0.0), 16.0) * lightIntensity * 0.15;\nvec3 shadedBlink = blinkColor * diff_lid + vec3(spec_lid) * smoothstep(lidRadius, lidRadius - 0.1, r);\nfinalEyeColor = mix(eyeColor, shadedBlink, lidMask);\nfloat lidAlpha = (r > lidRadius) ? 0.0 : 1.0 - smoothstep(lidRadius - 0.1, lidRadius, r);\nfinalAlphaMask = mix(finalAlphaMask, lidAlpha, lidMask);\n}\n}\nvec3 bg = mix(source.rgb, vec3(0.0), mask);\nvec3 finalColor = mix(bg, finalEyeColor, mask * finalAlphaMask);\nreturn vec4(finalColor, source.a);\n}",
