    code: "// NAME: Morphed Symmetrical Hexagon\nuniform float morphAmount; // @min 0.0 @max 1.0 @default 0.3\nuniform float speed; // @min 0.0 @max 5.0 @default 1.0\nuniform float intensity; // @min 0.0 @max 1.5 @default 0.5\nuniform float scale; // @min 0.1 @max 5.0 @default 0.3\nuniform float effectAmount; // @min 0.0 @max 1.0 @default 1.0\nuniform float blackLineScale; // @min 0.01 @max 1.0 @default 0.15\nuniform float blackLineThickness; // @min 0.01 @max 2.0 @default 0.1\nuniform float blackLineSpeed; // @min -5.0 @max 5.0 @default -1.0\nuniform float blackLineBlur; // @min 0.0 @max 2.0 @default 0.5\n#define R3 1.732051\nvec4 HexCoords(vec2 uv) {\nvec2 s = vec2(1.0, R3);\nvec2 h = 0.5 * s;\nvec2 gv = s * uv;\nvec2 a = mod(gv, s) - h;\nvec2 b = mod(gv + h, s) - h;\nvec2 ab = dot(a, a) < dot(b, b) ? a : b;\nreturn vec4(ab, gv - ab);\n}\nfloat GetSize(vec2 id, float seed, float time) {\nfloat d = length(id);\nfloat t = time * 0.5;\nreturn (sin(d * seed + t) + sin(d * seed * seed * 10.0 + t * 2.0)) / 2.0 + 0.5;\n}\nmat2 Rot(float a) {\nfloat s = sin(a), c = cos(a);\nreturn mat2(c, -s, s, c);\n}\nfloat Hexagon(vec2 uv, float r, float time, float thickness, float blur) {\nuv *= Rot(mix(0.0, 3.1415, r));\nr /= 0.7071;\nuv = vec2(-uv.y, uv.x);\nuv.x *= R3;\nuv = abs(uv);\nfloat d = dot(uv, normalize(vec2(1.0, 1.0))) - r;\nd = max(d, uv.y - r * 0.707);\nfloat edge = smoothstep(0.06 * thickness + blur, 0.02 * thickness, abs(d));\nfloat glow = smoothstep(0.25 * thickness + blur, 0.0, abs(d)) * 2.5;\nreturn edge + glow + smoothstep(0.1 * thickness + blur, 0.09 * thickness, abs(r - 0.5)) * sin(time);\n}\nfloat Layer(vec2 uv, float s, float time, float thickness, float blur) {\nvec4 hu = HexCoords(uv * 2.0);\nfloat d = Hexagon(hu.xy, GetSize(hu.zw, s, time), time, thickness, blur);\nvec2 offs = vec2(1.0, 0.0);\nd += Hexagon(hu.xy - offs, GetSize(hu.zw + offs, s, time), time, thickness, blur);\nd += Hexagon(hu.xy + offs, GetSize(hu.zw - offs, s, time), time, thickness, blur);\noffs = vec2(0.5, 0.8725);\nd += Hexagon(hu.xy - offs, GetSize(hu.zw + offs, s, time), time, thickness, blur);\nd += Hexagon(hu.xy + offs, GetSize(hu.zw - offs, s, time), time, thickness, blur);\noffs = vec2(-0.5, 0.8725);\nd += Hexagon(hu.xy - offs, GetSize(hu.zw + offs, s, time), time, thickness, blur);\nd += Hexagon(hu.xy + offs, GetSize(hu.zw - offs, s, time), time, thickness, blur);\nreturn d;\n}\nfloat N(float p) {\nreturn fract(sin(p * 123.34) * 345.456);\n}\nvec3 Col(float p, float offs) {\nfloat n = N(p) * 1234.34;\nreturn sin(n * vec3(12.23, 45.23, 56.2) + offs * 3.0) * 0.5 + 0.5;\n}\nvec3 GetAnimColor(vec2 UV, float time, float duv, float thickness, float blur, float timeMult) {\nfloat t = time * speed * timeMult * 0.5 + 5.0;\nvec2 p_uv = UV * mix(1.0, 5.0, sin(t * 0.5) * 0.5 + 0.5) * scale;\np_uv *= Rot(t);\np_uv.x *= R3;\nvec3 col = vec3(0.0);\nfor(float i = 0.0; i < 1.0; i += 0.3333) {\nfloat id = floor(i + t);\nfloat ft = fract(i + t);\nfloat z = mix(5.0, 0.1, ft);\nfloat fade = smoothstep(0.0, 0.3, ft) * smoothstep(1.0, 0.7, ft);\ncol += fade * ft * Layer(p_uv * z, N(i + id), time, thickness, blur) * Col(id, duv);\n}\nreturn col;\n}\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\nvec4 source = texture2D(tex, uv);\nfloat lum = dot(source.rgb, vec3(0.299, 0.587, 0.114));\nvec2 distortedUV = uv;\ndistortedUV.y -= lum * morphAmount;\ndistortedUV.x += (uv.x - 0.5) * 2.0 * lum * morphAmount * 0.2;\nvec2 UV = distortedUV - 0.5;\nUV.x *= resolution.x / resolution.y;\nfloat duv = dot(UV, UV);\nUV.x = abs(UV.x);\nvec3 col1 = GetAnimColor(UV, time, duv, 1.0, 0.0, 1.0);\nvec3 illuminatedColor = source.rgb * col1 * 2.0 * intensity;\nfloat illumFactor = clamp(length(col1 * intensity), 0.0, 1.0);\nvec3 invertedSource = 1.0 - source.rgb;\nfloat brightness = dot(source.rgb, vec3(0.299, 0.587, 0.114));\ninvertedSource *= smoothstep(0.05, 0.2, brightness);\nvec3 effectColor = mix(invertedSource, illuminatedColor, illumFactor);\nvec3 finalColor = mix(source.rgb, effectColor, effectAmount);\nfloat whiteness = min(finalColor.r, min(finalColor.g, finalColor.b));\nfloat mask = smoothstep(0.8, 1.0, whiteness);\nif (mask > 0.0) {\nvec3 col2 = GetAnimColor(UV, time, duv, 1.0, 0.0, -1.0);\nvec3 reverseIlluminated = source.rgb * col2 * 2.0 * intensity;\nfinalColor = mix(finalColor, reverseIlluminated, mask);\n}\nvec3 col3 = GetAnimColor(UV * blackLineScale, time, duv, blackLineThickness, blackLineBlur, blackLineSpeed);\nfloat blackMask = smoothstep(0.2, 0.8, length(col3));\nfinalColor = mix(finalColor, vec3(0.0), blackMask * effectAmount * 0.85);\nreturn vec4(clamp(finalColor, 0.0, 1.0), source.a);\n}",
