    description: "Imported from shadertoexport for Sculpture and Stage use.",
    code: "// NAME: Noisy Color Map\nuniform float scale; // @min 2.0 @max 20.0 @default 10.0\nuniform float noiseStrength; // @min 0.0 @max 3.0 @default 1.2\nuniform float colorDensity; // @min 1.0 @max 20.0 @default 6.0\nuniform float lineDensity; // @min 5.0 @max 50.0 @default 20.0\nuniform float blackThreshold; // @min 0.0 @max 1.0 @default 0.1\nuniform float speed; // @min 0.0 @max 5.0 @default 1.0\nuniform float sourceMix; // @min 0.0 @max 1.0 @default 0.25\nuniform float saturation; // @min 0.0 @max 2.0 @default 1.3\nuniform vec3 colorA; // @default 1.0,0.1,0.4\nuniform vec3 colorB; // @default 0.1,0.8,1.0\nuniform vec3 colorC; // @default 0.8,1.0,0.1\n\nvec4 processColor(sampler2D tex, vec2 uv, float time, vec2 resolution) {\n    vec4 source = texture2D(tex, uv);\n\n    float lum = dot(source.rgb, vec3(0.299, 0.587, 0.114));\n    float mask = smoothstep(blackThreshold, blackThreshold + 0.05, lum);\n\n    vec2 aspect = vec2(resolution.x / max(resolution.y, 1.0), 1.0);\n    vec2 p = uv * aspect * scale;\n    float t = time * speed;\n\n    float noiseLow = node_noise(p * 0.45 + vec2(t * 0.12, -t * 0.09));\n    float noiseMid = node_noise(p + vec2(-t * 0.25, t * 0.18));\n    float noiseHigh = node_noise(p * 2.1 + vec2(t * 0.4, t * 0.3));\n\n    float noiseMap = noiseLow * 0.5 + noiseMid * 0.35 + noiseHigh * 0.15;\n    noiseMap = clamp(noiseMap * noiseStrength + lum * 0.8, 0.0, 1.0);\n\n    float colorPosition = fract(\n        noiseMap * colorDensity +\n        lum * 1.5 +\n        sin((uv.x + uv.y) * 6.28318 + t * 0.35) * 0.12\n    );\n\n    float blendAB = smoothstep(0.0, 0.5, colorPosition);\n    float blendBC = smoothstep(0.5, 1.0, colorPosition);\n\n    vec3 mappedColor = mix(colorA, colorB, blendAB);\n    mappedColor = mix(mappedColor, colorC, blendBC);\n\n    vec3 rainbow = 0.5 + 0.5 * cos(\n        6.28318 * (\n            colorPosition +\n            vec3(0.0, 0.3333, 0.6667)\n        )\n    );\n\n    mappedColor = mix(mappedColor, rainbow, 0.55);\n\n    float topo = sin(\n        (\n            noiseMap * 2.5 +\n            lum * 1.8 +\n            uv.x * 2.0 +\n            uv.y * 2.0 -\n            t * 0.3\n        ) * lineDensity\n    );\n\n    float lines = smoothstep(0.72, 0.98, topo);\n    float glow = smoothstep(0.35, 1.0, noiseMap) * (0.35 + lum * 0.9);\n\n    mappedColor *= 0.55 + glow;\n    mappedColor += rainbow * lines * (0.25 + lum * 0.75);\n\n    float mappedLum = dot(mappedColor, vec3(0.299, 0.587, 0.114));\n    mappedColor = mix(vec3(mappedLum), mappedColor, saturation);\n    mappedColor = clamp(mappedColor, 0.0, 1.0);\n\n    vec3 finalColor = mix(mappedColor, source.rgb, sourceMix);\n    float finalAlpha = source.a * mask;\n\n    return vec4(finalColor * finalAlpha, finalAlpha);\n}",
